from typing import Dict, List, TypedDict
from datetime import datetime
import uuid



class RoomInfo(TypedDict):
    room_id: str
    room_type: str
    status: str  # 'available', 'occupied', or 'reserved'
    amenities: List[str]

class BookingInfo(TypedDict):
    booking_id: str
    room_id: str
    guest_id: str
    check_in_date: str  # could use datetime in real implementation
    check_out_date: str
    status: str  # e.g., 'active', 'cancelled', etc.

class GuestInfo(TypedDict):
    guest_id: str
    name: str
    contact_info: str

class HotelRoomReservationSystem:
    def __init__(self, init_config: dict):
        """
        Hotel room reservation system stateful environment.
        init_config: external initializer (not implemented here).
        """

        # Rooms: {room_id: RoomInfo}
        # (Represents each physical room; status is one of 'available', 'occupied', or 'reserved')
        self.rooms: Dict[str, RoomInfo] = {}

        # Bookings: {booking_id: BookingInfo}
        # (Each booking links a guest and a room over a time range)
        self.bookings: Dict[str, BookingInfo] = {}

        # Guests: {guest_id: GuestInfo}
        # (Contact info for guests)
        self.guests: Dict[str, GuestInfo] = {}

        # Constraints:
        # - Each room has only one status at a time: 'available', 'occupied', or 'reserved'.
        # - Room availability is updated in real-time based on bookings, check-in, and check-out.
        # - Bookings must be made for valid rooms and valid date ranges (no overlap for the same room).
        # - Only rooms with status == 'available' are returned in availability queries.

        self.init_config = init_config

    def list_available_rooms(self) -> dict:
        """
        Retrieve the list of all rooms currently marked as 'available'.

        Returns:
            dict: {
                "success": True,
                "data": List[RoomInfo],  # List of available rooms (may be empty if none)
            }

        Constraints:
            - Only rooms with status == 'available' are included.
            - A room's status is always one of: 'available', 'occupied', 'reserved'.
        """
        available_rooms = [
            room_info for room_info in self.rooms.values()
            if room_info["status"] == "available"
        ]

        return { "success": True, "data": available_rooms }

    def list_available_rooms_by_type(self, room_type: str) -> dict:
        """
        Retrieve all rooms with status "available", filtered by the given room type.

        Args:
            room_type (str): Room type to filter (e.g., "single", "double", "suite").

        Returns:
            dict:
                success: True
                data: List[RoomInfo] -- all available rooms of matching type (may be empty)
            or
                success: False
                error: str -- description of the error (unexpected case)

        Constraints:
            - Only rooms where status == "available" and room_type matches are returned.
            - If no rooms match, data is empty list.
        """
        filtered_rooms = [
            room_info for room_info in self.rooms.values()
            if room_info["status"] == "available" and room_info["room_type"] == room_type
        ]
        return { "success": True, "data": filtered_rooms }

    def get_room_info(self, room_id: str) -> dict:
        """
        Fetch complete details of a specific room specified by room_id.

        Args:
            room_id (str): The unique identifier for the room.

        Returns:
            dict: 
                Success: {
                    "success": True,
                    "data": RoomInfo  # Dictionary of all room attributes
                }
                Failure: {
                    "success": False,
                    "error": str  # e.g. "Room does not exist"
                }

        Constraints:
            - The given room_id must exist in the hotel system.
        """
        room = self.rooms.get(room_id)
        if room is None:
            return { "success": False, "error": "Room does not exist" }
        return { "success": True, "data": room }

    def get_room_amenities(self, room_id: str) -> dict:
        """
        List the amenities/features associated with a specific room.

        Args:
            room_id (str): Unique identifier for the room.

        Returns:
            dict: 
              On success:
                {
                    "success": True,
                    "data": List[str]  # Amenities/features for the room
                }
              On failure:
                {
                    "success": False,
                    "error": str  # Reason for error, e.g., room not found
                }

        Constraints:
            - The provided room_id must exist in the system.
        """
        room_info = self.rooms.get(room_id)
        if not room_info:
            return { "success": False, "error": "Room not found" }

        return { "success": True, "data": room_info.get("amenities", []) }

    def list_all_room_types(self) -> dict:
        """
        Retrieve all distinct room types currently present in the hotel.

        Args:
            None

        Returns:
            dict: {
                "success": True,
                "data": List[str]  # List of distinct room types (may be empty if no rooms)
            }

        Constraints:
            - Duplicates are not allowed in the returned list.
            - If no rooms exist, returns an empty list as data.
        """
        room_types = set()
        for room_info in self.rooms.values():
            rt = room_info.get("room_type")
            if rt:
                room_types.add(rt)

        return { "success": True, "data": list(room_types) }

    def list_bookings_by_guest(self, guest_id: str) -> dict:
        """
        Retrieve all bookings made by a particular guest.

        Args:
            guest_id (str): The ID of the guest whose bookings are to be retrieved.

        Returns:
            dict: {
                "success": True,
                "data": List[BookingInfo],  # List of bookings (could be empty if none found)
            }
            or
            {
                "success": False,
                "error": str  # Error description, e.g., "Guest not found"
            }

        Constraints:
            - The guest_id must exist in the hotel guest registry.
        """
        if guest_id not in self.guests:
            return {"success": False, "error": "Guest not found"}

        bookings = [
            booking_info for booking_info in self.bookings.values()
            if booking_info["guest_id"] == guest_id
        ]

        return {"success": True, "data": bookings}

    def get_booking_info(self, booking_id: str) -> dict:
        """
