    def list_active_bookings_for_room(self, room_id: str) -> dict:
        """
        List all active bookings associated with the specified room.

        Args:
            room_id (str): Unique identifier of the room to query.

        Returns:
            dict:
                {
                    "success": True,
                    "data": List[BookingInfo],  # May be empty if no active bookings
                }
                or
                {
                    "success": False,
                    "error": str  # Reason for failure ('Room does not exist')
                }

        Constraints:
            - Room must exist in the system.
            - Only bookings with status == 'active' for the specified room are included.
        """
        if room_id not in self.rooms:
            return { "success": False, "error": "Room does not exist" }

        active_bookings = [
            booking_info for booking_info in self.bookings.values()
            if booking_info["room_id"] == room_id and booking_info["status"] == "active"
        ]

        return { "success": True, "data": active_bookings }

    def check_room_availability_over_date_range(
        self, room_id: str, requested_check_in_date: str, requested_check_out_date: str
    ) -> dict:
        """
        Confirm if the given room is available for the requested date range.

        Args:
            room_id (str): Room identifier to check.
            requested_check_in_date (str): Requested check-in date (format 'YYYY-MM-DD').
            requested_check_out_date (str): Requested check-out date (exclusive).

        Returns:
            dict: {
                "success": True,
                "data": { "available": bool, "reason": str (when unavailable) }
            }
            or
            { "success": False, "error": str }

        Constraints:
            - Room must exist in the system.
            - Requested date range must not overlap with any 'active' bookings for the room.
            - Bookings with status other than 'active' are ignored.
            - Basic string date compare for simplicity.
        """

        if room_id not in self.rooms:
            return { "success": False, "error": "Room does not exist." }

        # Check against existing active bookings for this room
        for booking in self.bookings.values():
            if booking["room_id"] != room_id:
                continue
            if booking["status"] != "active":
                continue
            # Check for overlap: (existing_in < requested_out) and (requested_in < existing_out)
            existing_in = booking["check_in_date"]
            existing_out = booking["check_out_date"]
            if (
                existing_in < requested_check_out_date and
                requested_check_in_date < existing_out
            ):
                # Overlaps
                return {
                    "success": True,
                    "data": {
                        "available": False,
                        "reason": "Room is already booked during the requested dates."
                    }
                }
        # If no active overlapping booking found
        return { "success": True, "data": { "available": True } }

    def create_booking(
        self,
        room_id: str,
        guest_id: str,
        check_in_date: str,
        check_out_date: str
    ) -> dict:
        """
        Reserve a room for a guest over valid dates (with no overlaps) and update the room status to 'reserved'.

        Args:
            room_id (str): The ID of the room to be booked.
            guest_id (str): The ID of the guest making the booking.
            check_in_date (str): Booking start date (format: 'YYYY-MM-DD').
            check_out_date (str): Booking end date (exclusive; format: 'YYYY-MM-DD').

        Returns:
            dict: {
                "success": True,
                "message": "Booking created for room X by guest Y from date A to B."
            }
            or
            {
                "success": False,
                "error": "reason"
            }

        Constraints:
            - Room must exist and be 'available'.
            - Guest must exist.
            - Booking dates must not overlap any active booking for the room.
            - Dates: check_in_date < check_out_date.
            - Room status is set to 'reserved' after booking.
        """
        # Check room exists
        room = self.rooms.get(room_id)
        if not room:
            return {"success": False, "error": f"Room {room_id} does not exist."}

        # Check guest exists
        guest = self.guests.get(guest_id)
        if not guest:
            return {"success": False, "error": f"Guest {guest_id} does not exist."}

        # Check date validity
        try:
            in_date = datetime.strptime(check_in_date, "%Y-%m-%d").date()
            out_date = datetime.strptime(check_out_date, "%Y-%m-%d").date()
            if in_date >= out_date:
                return {"success": False, "error": "Check-in date must be before check-out date."}
        except Exception:
            return {"success": False, "error": "Invalid date format. Use YYYY-MM-DD."}

        # Only allow booking if room is available
        if room["status"] != "available":
            return {"success": False, "error": f"Room {room_id} is not available for booking."}

        # Check for booking overlap
        def overlaps(a_start, a_end, b_start, b_end):
            # Returns True if [a_start, a_end) overlaps with [b_start, b_end)
            return not (a_end <= b_start or a_start >= b_end)

        for booking in self.bookings.values():
            if booking["room_id"] == room_id and booking["status"] == "active":
                try:
                    b_in = datetime.strptime(booking["check_in_date"], "%Y-%m-%d").date()
                    b_out = datetime.strptime(booking["check_out_date"], "%Y-%m-%d").date()
                    if overlaps(in_date, out_date, b_in, b_out):
                        return {"success": False, "error": "Requested dates overlap with an active booking for this room."}
                except Exception:
                    continue # ignore corrupted bookings

        # Create booking_id (simple increment or UUID)
        booking_id = str(uuid.uuid4())

        # Create new booking
        new_booking = {
            "booking_id": booking_id,
            "room_id": room_id,
            "guest_id": guest_id,
            "check_in_date": check_in_date,
            "check_out_date": check_out_date,
            "status": "active"
        }
        self.bookings[booking_id] = new_booking

        # Update room status to reserved
        self.rooms[room_id]["status"] = "reserved"

        return {
            "success": True,
            "message": f"Booking created for room {room_id} by guest {guest_id} from {check_in_date} to {check_out_date}."
        }

    def cancel_booking(self, booking_id: str) -> dict:
        """
        Cancel a booking and update the associated room's status appropriately.

        Args:
            booking_id (str): The unique booking ID to cancel.

        Returns:
            dict: {
                "success": True,
                "message": "Booking cancelled and room status updated."
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure (e.g., no such booking, already cancelled)
            }

        Constraints:
            - Only active bookings can be cancelled.
            - After cancellation, room status should be set to 'available' if there are
              no overlapping active bookings and room is not 'occupied'.
            - The room must exist.
        """

        booking = self.bookings.get(booking_id)
        if not booking:
            return { "success": False, "error": "Booking does not exist." }

        if booking["status"] == "cancelled":
            return { "success": False, "error": "Booking already cancelled." }

        room_id = booking["room_id"]
        room = self.rooms.get(room_id)
        if not room:
            return { "success": False, "error": "Associated room does not exist." }

        # Cancel the booking
        booking["status"] = "cancelled"

        # After cancellation, check if room should become available
        # Conditions: Room must not be 'occupied', and must have no other active bookings
        room_is_occupied = room["status"] == "occupied"

        has_active_booking = False
        for other_booking in self.bookings.values():
            if (
                other_booking["room_id"] == room_id and
                other_booking["status"] != "cancelled" and
                other_booking["booking_id"] != booking_id
            ):
                has_active_booking = True
                break

        # Only set to available if not occupied and no other active bookings
        if (not room_is_occupied) and (not has_active_booking):
            room["status"] = "available"

        return { "success": True, "message": "Booking cancelled and room status updated." }

    def check_in_guest(self, booking_id: str) -> dict:
        """
        Mark the room for the specified booking as 'occupied' to indicate the guest has checked in.

        Args:
            booking_id (str): The unique booking ID for the reservation.

        Returns:
            dict: {
                "success": True,
                "message": "Guest checked in. Room marked as occupied."
            }
            or
            {
                "success": False,
                "error": str  # error description (e.g., booking does not exist, room not reserved, etc.)
            }

        Constraints:
            - Booking must exist and be 'active' (not cancelled).
            - Room must exist.
            - Room's current status must be 'reserved' (can only check-in to reserved rooms).
            - Updates the room's status to 'occupied'. Adjust booking status if needed.
        """
        booking = self.bookings.get(booking_id)
        if not booking:
            return {"success": False, "error": "Booking does not exist."}

        if booking["status"] != "active":
            return {"success": False, "error": "Booking is not active."}

        room_id = booking["room_id"]
        room = self.rooms.get(room_id)
        if not room:
            return {"success": False, "error": "Room for booking does not exist."}

        if room["status"] != "reserved":
            return {"success": False, "error": "Room is not reserved and cannot be checked in."}

        # Mark the room as occupied
        room["status"] = "occupied"
        self.rooms[room_id] = room  # Ensure update (may not be necessary with direct dict)

        # Optionally, update booking status to 'checked-in'
        booking["status"] = "checked-in"
        self.bookings[booking_id] = booking

        return {"success": True, "message": "Guest checked in. Room marked as occupied."}

    def check_out_guest(self, room_id: str) -> dict:
        """
        Release an occupied room after a guest's departure, setting its status back to 'available'.

        Args:
            room_id (str): The unique identifier of the room to be checked out.

        Returns:
            dict: {
                "success": True,
                "message": str  # Confirmation message describing the checkout
            }
            or
            {
                "success": False,
                "error": str  # Error description, e.g., room not found or not occupied
            }

        Constraints:
            - The room must exist.
            - The room's current status must be 'occupied'.
            - After check-out, room status is set to 'available'.
            - Related active booking status can be marked as 'checked_out' if such booking exists.
        """
        room_info = self.rooms.get(room_id)
        if not room_info:
            return {"success": False, "error": "Room not found."}

        if room_info["status"] != "occupied":
            return {"success": False, "error": "Room is not currently occupied and cannot be checked out."}

        # Set room status to 'available'
        room_info["status"] = "available"

        # Optionally, update active booking for this room to 'checked_out' if exists
        for booking in self.bookings.values():
            if booking["room_id"] == room_id and booking["status"] == "active":
                booking["status"] = "checked_out"
                # (Optionally record checkout date or time here, not specified in schema)

        return {
            "success": True,
            "message": f"Room '{room_id}' has been successfully checked out and is now available."
        }

    def update_room_status(self, room_id: str, new_status: str) -> dict:
        """
        Directly set the status of a specific room.

        Args:
            room_id (str): The ID of the room to update.
            new_status (str): The new status for the room ("available", "occupied", or "reserved").

        Returns:
            dict: {
                "success": True,
                "message": "Room status updated successfully."
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure (invalid room ID or invalid status)
            }

        Constraints:
            - Only allowed statuses: "available", "occupied", "reserved".
            - The room must exist.
        """
        allowed_statuses = {"available", "occupied", "reserved"}
        if room_id not in self.rooms:
            return { "success": False, "error": "Room ID does not exist." }
        if new_status not in allowed_statuses:
            return { "success": False, "error": "Invalid status. Allowed: available, occupied, reserved." }

        self.rooms[room_id]["status"] = new_status
        return { "success": True, "message": "Room status updated successfully." }

    def update_guest_info(self, guest_id: str, name: str = None, contact_info: str = None) -> dict:
        """
        Modify name/contact information for a guest.

        Args:
            guest_id (str): The ID of the guest to update.
            name (str, optional): The new name for the guest.
            contact_info (str, optional): The new contact info for the guest.

        Returns:
            dict: {
                "success": True,
                "message": "Guest info updated"
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - The guest_id must exist in the system.
            - At least one update field (name or contact_info) must be provided.
        """
        if guest_id not in self.guests:
            return { "success": False, "error": "Guest not found" }

        if name is None and contact_info is None:
            return { "success": False, "error": "No update fields provided" }

        if name is not None:
            self.guests[guest_id]['name'] = name
        if contact_info is not None:
            self.guests[guest_id]['contact_info'] = contact_info

        return { "success": True, "message": "Guest info updated" }

    def delete_booking(self, booking_id: str) -> dict:
        """
        Remove a booking record from the system.

        Args:
            booking_id (str): The unique identifier of the booking to remove.

        Returns:
            dict:
                {
                    "success": True,
                    "message": "Booking deleted successfully."
                }
                OR
                {
                    "success": False,
                    "error": "Booking not found."
                }

        Constraints:
            - Only existing bookings can be deleted.
            - After deletion, if the room had only this active booking and no other active or reserved bookings, its status should be updated to 'available'.
        """
        booking_info = self.bookings.get(booking_id)
        if not booking_info:
            return { "success": False, "error": "Booking not found." }

        room_id = booking_info["room_id"]
        # Remove the booking
        del self.bookings[booking_id]

        # Check if room status needs updating
        room_info = self.rooms.get(room_id)
        if room_info:
            # See if any remaining bookings for this room are 'active' or 'reserved'
            has_active_or_reserved = any(
                (b["room_id"] == room_id and b["status"] in ("active", "reserved"))
                for b in self.bookings.values()
            )
            # If none are active/reserved, make the room "available"
            if not has_active_or_reserved:
                room_info["status"] = "available"
                self.rooms[room_id] = room_info  # Update in state

        return { "success": True, "message": "Booking deleted successfully." }

    def add_room(self, room_id: str, room_type: str, status: str, amenities: list) -> dict:
        """
        Add a new room into the hotel system.

        Args:
            room_id (str): Unique identifier for the room.
            room_type (str): Type of the room (e.g., 'single', 'double').
            status (str): Initial status ('available', 'occupied', 'reserved').
            amenities (list): List of amenities/features for the room.

        Returns:
            dict: {
                "success": True,
                "message": str  # Confirmation message
            }
            or
            {
                "success": False,
                "error": str  # Description of the error
            }

        Constraints:
            - room_id must be unique (not present in self.rooms).
            - status must be one of: 'available', 'occupied', 'reserved'.
            - amenities must be a list.
            - Required fields must not be missing.
        """
        VALID_STATUSES = {'available', 'occupied', 'reserved'}

        if not room_id or not room_type or not status or amenities is None:
            return {"success": False, "error": "Missing one or more required fields."}

        if room_id in self.rooms:
            return {"success": False, "error": f"Room ID '{room_id}' already exists."}

        if status not in VALID_STATUSES:
            return {"success": False, "error": f"Invalid room status: {status}. Must be 'available', 'occupied', or 'reserved'."}

        if not isinstance(amenities, list):
            return {"success": False, "error": "Amenities must be provided as a list."}

        # Add the new room
        new_room: RoomInfo = {
            "room_id": room_id,
            "room_type": room_type,
            "status": status,
            "amenities": amenities
        }
        self.rooms[room_id] = new_room

        return {
            "success": True,
            "message": f"Room '{room_id}' successfully added."
        }

    def update_room_amenities(self, room_id: str, amenities: list) -> dict:
        """
        Change or update the list of amenities/features for an existing room.

        Args:
            room_id (str): Unique identifier of the room to update.
            amenities (list of str): New list of amenities for the room.

        Returns:
            dict: {
                "success": True,
                "message": "Room amenities updated."
            }
            or
            {
                "success": False,
                "error": "Room not found."
            }

        Constraints:
            - The room must exist (room_id must be present in the system).
        """
        if room_id not in self.rooms:
            return { "success": False, "error": "Room not found." }

        self.rooms[room_id]["amenities"] = amenities

        return { "success": True, "message": "Room amenities updated." }

