def check_room_availability_over_date_range(
    self, room_id: str, requested_check_in_date: str, requested_check_out_date: str
) -> dict:
    """
    Confirm if the given room is available for the requested date range.

    Args:
        room_id (str): Room identifier to check.
        requested_check_in_date (str): Requested check-in date (format 'YYYY-MM-DD').
        requested_check_out_date (str): Requested check-out date (exclusive).

    Returns:
        dict: {
            "success": True,
            "data": { "available": bool, "reason": str (when unavailable) }
        }
        or
        { "success": False, "error": str }

    Constraints:
        - Room must exist in the system.
        - Requested date range must not overlap with any 'active' bookings for the room.
        - Bookings with status other than 'active' are ignored.
        - Basic string date compare for simplicity.
    """

    if room_id not in self.rooms:
        return { "success": False, "error": "Room does not exist." }

    # Check against existing active bookings for this room
    for booking in self.bookings.values():
        if booking["room_id"] != room_id:
            continue
        if booking["status"] != "active":
            continue
        # Check for overlap: (existing_in < requested_out) and (requested_in < existing_out)
        existing_in = booking["check_in_date"]
        existing_out = booking["check_out_date"]
        if (
            existing_in < requested_check_out_date and
            requested_check_in_date < existing_out
        ):
            # Overlaps
            return {
                "success": True,
                "data": {
                    "available": False,
                    "reason": "Room is already booked during the requested dates."
                }
            }
    # If no active overlapping booking found
    return { "success": True, "data": { "available": True } }

create_booking.source_code:
def create_booking(
    self,
    room_id: str,
    guest_id: str,
    check_in_date: str,
    check_out_date: str
) -> dict:
    """
    Reserve a room for a guest over valid dates (with no overlaps) and update the room status to 'reserved'.

    Args:
        room_id (str): The ID of the room to be booked.
        guest_id (str): The ID of the guest making the booking.
        check_in_date (str): Booking start date (format: 'YYYY-MM-DD').
        check_out_date (str): Booking end date (exclusive; format: 'YYYY-MM-DD').

    Returns:
        dict: {
            "success": True,
            "message": "Booking created for room X by guest Y from date A to B."
        }
        or
        {
            "success": False,
            "error": "reason"
        }

    Constraints:
        - Room must exist and be 'available'.
        - Guest must exist.
        - Booking dates must not overlap any active booking for the room.
        - Dates: check_in_date < check_out_date.
        - Room status is set to 'reserved' after booking.
    """
    # Check room exists
    room = self.rooms.get(room_id)
    if not room:
        return {"success": False, "error": f"Room {room_id} does not exist."}

    # Check guest exists
    guest = self.guests.get(guest_id)
    if not guest:
        return {"success": False, "error": f"Guest {guest_id} does not exist."}

    # Check date validity
    try:
        in_date = datetime.strptime(check_in_date, "%Y-%m-%d").date()
        out_date = datetime.strptime(check_out_date, "%Y-%m-%d").date()
        if in_date >= out_date:
            return {"success": False, "error": "Check-in date must be before check-out date."}
    except Exception:
        return {"success": False, "error": "Invalid date format. Use YYYY-MM-DD."}

    # Only allow booking if room is available
    if room["status"] != "available":
        return {"success": False, "error": f"Room {room_id} is not available for booking."}

    # Check for booking overlap
    def overlaps(a_start, a_end, b_start, b_end):
        # Returns True if [a_start, a_end) overlaps with [b_start, b_end)
        return not (a_end <= b_start or a_start >= b_end)

    for booking in self.bookings.values():
        if booking["room_id"] == room_id and booking["status"] == "active":
            try:
                b_in = datetime.strptime(booking["check_in_date"], "%Y-%m-%d").date()
                b_out = datetime.strptime(booking["check_out_date"], "%Y-%m-%d").date()
                if overlaps(in_date, out_date, b_in, b_out):
                    return {"success": False, "error": "Requested dates overlap with an active booking for this room."}
            except Exception:
                continue # ignore corrupted bookings

    # Create booking_id (simple increment or UUID)
    booking_id = str(uuid.uuid4())

    # Create new booking
    new_booking = {
        "booking_id": booking_id,
        "room_id": room_id,
        "guest_id": guest_id,
        "check_in_date": check_in_date,
        "check_out_date": check_out_date,
        "status": "active"
    }
    self.bookings[booking_id] = new_booking

    # Update room status to reserved
    self.rooms[room_id]["status"] = "reserved"

    return {
        "success": True,
        "message": f"Booking created for room {room_id} by guest {guest_id} from {check_in_date} to {check_out_date}."
    }

