def check_in_guest(self, booking_id: str) -> dict:
    """
    Mark the room for the specified booking as 'occupied' to indicate the guest has checked in.

    Args:
        booking_id (str): The unique booking ID for the reservation.

    Returns:
        dict: {
            "success": True,
            "message": "Guest checked in. Room marked as occupied."
        }
        or
        {
            "success": False,
            "error": str  # error description (e.g., booking does not exist, room not reserved, etc.)
        }

    Constraints:
        - Booking must exist and be 'active' (not cancelled).
        - Room must exist.
        - Room's current status must be 'reserved' (can only check-in to reserved rooms).
        - Updates the room's status to 'occupied'. Adjust booking status if needed.
    """
    booking = self.bookings.get(booking_id)
    if not booking:
        return {"success": False, "error": "Booking does not exist."}

    if booking["status"] != "active":
        return {"success": False, "error": "Booking is not active."}

    room_id = booking["room_id"]
    room = self.rooms.get(room_id)
    if not room:
        return {"success": False, "error": "Room for booking does not exist."}

    if room["status"] != "reserved":
        return {"success": False, "error": "Room is not reserved and cannot be checked in."}

    # Mark the room as occupied
    room["status"] = "occupied"
    self.rooms[room_id] = room  # Ensure update (may not be necessary with direct dict)

    # Optionally, update booking status to 'checked-in'
    booking["status"] = "checked-in"
    self.bookings[booking_id] = booking

    return {"success": True, "message": "Guest checked in. Room marked as occupied."}

check_out_guest.source_code:
def check_out_guest(self, room_id: str) -> dict:
    """
    Release an occupied room after a guest's departure, setting its status back to 'available'.

    Args:
        room_id (str): The unique identifier of the room to be checked out.

    Returns:
        dict: {
            "success": True,
            "message": str  # Confirmation message describing the checkout
        }
        or
        {
            "success": False,
            "error": str  # Error description, e.g., room not found or not occupied
        }

    Constraints:
        - The room must exist.
        - The room's current status must be 'occupied'.
        - After check-out, room status is set to 'available'.
        - Related active booking status can be marked as 'checked_out' if such booking exists.
    """
    room_info = self.rooms.get(room_id)
    if not room_info:
        return {"success": False, "error": "Room not found."}

    if room_info["status"] != "occupied":
        return {"success": False, "error": "Room is not currently occupied and cannot be checked out."}

    # Set room status to 'available'
    room_info["status"] = "available"

    # Optionally, update active booking for this room to 'checked_out' if exists
    for booking in self.bookings.values():
        if booking["room_id"] == room_id and booking["status"] == "active":
            booking["status"] = "checked_out"
            # (Optionally record checkout date or time here, not specified in schema)

    return {
        "success": True,
        "message": f"Room '{room_id}' has been successfully checked out and is now available."
    }

