def delete_booking(self, booking_id: str) -> dict:
    """
    Remove a booking record from the system.

    Args:
        booking_id (str): The unique identifier of the booking to remove.

    Returns:
        dict:
            {
                "success": True,
                "message": "Booking deleted successfully."
            }
            OR
            {
                "success": False,
                "error": "Booking not found."
            }

    Constraints:
        - Only existing bookings can be deleted.
        - After deletion, if the room had only this active booking and no other active or reserved bookings, its status should be updated to 'available'.
    """
    booking_info = self.bookings.get(booking_id)
    if not booking_info:
        return { "success": False, "error": "Booking not found." }

    room_id = booking_info["room_id"]
    # Remove the booking
    del self.bookings[booking_id]

    # Check if room status needs updating
    room_info = self.rooms.get(room_id)
    if room_info:
        # See if any remaining bookings for this room are 'active' or 'reserved'
        has_active_or_reserved = any(
            (b["room_id"] == room_id and b["status"] in ("active", "reserved"))
            for b in self.bookings.values()
        )
        # If none are active/reserved, make the room "available"
        if not has_active_or_reserved:
            room_info["status"] = "available"
            self.rooms[room_id] = room_info  # Update in state

    return { "success": True, "message": "Booking deleted successfully." }

