def add_room(self, room_id: str, room_type: str, status: str, amenities: list) -> dict:
    """
    Add a new room into the hotel system.

    Args:
        room_id (str): Unique identifier for the room.
        room_type (str): Type of the room (e.g., 'single', 'double').
        status (str): Initial status ('available', 'occupied', 'reserved').
        amenities (list): List of amenities/features for the room.

    Returns:
        dict: {
            "success": True,
            "message": str  # Confirmation message
        }
        or
        {
            "success": False,
            "error": str  # Description of the error
        }

    Constraints:
        - room_id must be unique (not present in self.rooms).
        - status must be one of: 'available', 'occupied', 'reserved'.
        - amenities must be a list.
        - Required fields must not be missing.
    """
    VALID_STATUSES = {'available', 'occupied', 'reserved'}

    if not room_id or not room_type or not status or amenities is None:
        return {"success": False, "error": "Missing one or more required fields."}

    if room_id in self.rooms:
        return {"success": False, "error": f"Room ID '{room_id}' already exists."}

    if status not in VALID_STATUSES:
        return {"success": False, "error": f"Invalid room status: {status}. Must be 'available', 'occupied', or 'reserved'."}

    if not isinstance(amenities, list):
        return {"success": False, "error": "Amenities must be provided as a list."}

    # Add the new room
    new_room: RoomInfo = {
        "room_id": room_id,
        "room_type": room_type,
        "status": status,
        "amenities": amenities
    }
    self.rooms[room_id] = new_room

    return {
        "success": True,
        "message": f"Room '{room_id}' successfully added."
    }

