from typing import Dict, TypedDict
from typing import Optional, Dict
import datetime
import uuid



class PatientInfo(TypedDict):
    patient_id: str
    name: str
    contact_info: str
    date_of_birth: str
    login_credential: str

class MedicalRecordInfo(TypedDict):
    record_id: str
    patient_id: str
    file_path: str
    file_type: str
    upload_datetime: str
    description: str
    access_permission: str

class AppointmentInfo(TypedDict):
    appointment_id: str
    patient_id: str
    provider_id: str
    appointment_datetime: str
    appointment_type: str
    status: str

class ProviderInfo(TypedDict):
    provider_id: str
    name: str
    specialization: str
    contact_info: str

class PatientHealthcarePortal:
    def __init__(self, init_config: dict):
        """
        Environment state for the healthcare portal.
        init_config: external initializer (not implemented here).
        """
        # Patients: {patient_id: PatientInfo}
        self.patients: Dict[str, PatientInfo] = {}
        # MedicalRecords: {record_id: MedicalRecordInfo}
        self.medical_records: Dict[str, MedicalRecordInfo] = {}
        # Appointments: {appointment_id: AppointmentInfo}
        self.appointments: Dict[str, AppointmentInfo] = {}
        # Providers: {provider_id: ProviderInfo}
        self.providers: Dict[str, ProviderInfo] = {}

        # Constraints and access control:
        # - Only authorized patients can upload medical records for their own appointments
        # - Medical records must be securely stored and access-controlled
        # - Uploaded files must be associated with the correct appointment and patient
        # - Medical record file types and size may be subject to restrictions
        # - Patients and providers can only access records according to permission settings

        self.init_config = init_config

    def get_patient_info(self, patient_id: str = None, name: str = None) -> dict:
        """
        Retrieve details for a patient by patient_id OR name.

        Args:
            patient_id (str, optional): The unique patient identifier.
            name (str, optional): The patient's name (not guaranteed unique).

        Returns:
            dict: 
                On success: 
                    {
                        "success": True,
                        "data": PatientInfo | List[PatientInfo]
                    }
                On failure:
                    {
                        "success": False,
                        "error": str
                    }

        Constraints:
            - At least one of patient_id or name must be provided.
            - If both are provided, patient_id takes precedence.
            - Name lookup returns all matching patients.
        """
        if patient_id:
            if patient_id in self.patients:
                return {"success": True, "data": self.patients[patient_id]}
            else:
                return {"success": False, "error": "Patient ID not found."}
        elif name:
            # Case-insensitive match for name
            matches = [
                patient_info for patient_info in self.patients.values()
                if patient_info["name"].lower() == name.lower()
            ]
            if matches:
                return {"success": True, "data": matches}
            else:
                return {"success": False, "error": "No patients found with the specified name."}
        else:
            return {"success": False, "error": "Either patient_id or name must be provided."}

    def get_appointment_by_patient(self, patient_id: str) -> dict:
        """
        Retrieve all scheduled appointments for the specified patient.

        Args:
            patient_id (str): The patient ID.

        Returns:
            dict: 
                - On success:
                    { "success": True, "data": List[AppointmentInfo] }
                - On failure:
                    { "success": False, "error": "Patient not found" }

        Constraints:
            - The patient ID must exist in the portal.
            - Returns an empty list if the patient has no scheduled appointments.
        """
        if patient_id not in self.patients:
            return { "success": False, "error": "Patient not found" }

        appointments = [
            info for info in self.appointments.values()
            if info['patient_id'] == patient_id
        ]
        return { "success": True, "data": appointments }


    def get_upcoming_appointments(self, patient_id: str, appointment_type: Optional[str] = None) -> dict:
        """
        List a patient's upcoming appointments, optionally filtered by appointment type.

        Args:
            patient_id (str): The ID of the patient to query.
            appointment_type (Optional[str]): If provided, filter appointments by this type.

        Returns:
            dict:
                {
                    "success": True,
                    "data": [AppointmentInfo, ...],  # May be empty if no appointments.
                }
                or
                {
                    "success": False,
                    "error": str
                }

        Constraints:
            - Only valid patient_id may be queried.
            - Upcoming appointments are those with status 'scheduled' or 'pending' and their datetime is in the future.
            - If appointment_type is provided, results are filtered accordingly.
        """

        # Check patient exists
        if patient_id not in self.patients:
            return { "success": False, "error": "Patient not found" }

        now = datetime.datetime.utcnow()

        # Acceptable upcoming statuses
        upcoming_statuses = {"scheduled", "pending"}

        result = []
        for appointment in self.appointments.values():
            # Filter by patient, status, future datetime, and optional type
            if appointment["patient_id"] != patient_id:
                continue
            if appointment["status"].lower() not in upcoming_statuses:
                continue
            # Parse the appointment datetime (assumed as ISO string)
            try:
                appointment_time = datetime.datetime.fromisoformat(appointment["appointment_datetime"])
            except Exception:
                continue  # Skip if invalid datetime
            if appointment_time < now:
                continue
            if appointment_type is not None and appointment["appointment_type"] != appointment_type:
                continue
            result.append(appointment)

        return { "success": True, "data": result }

    def get_appointment_details(self, appointment_id: str) -> dict:
        """
        Retrieve the complete details of a specific appointment by its appointment_id.

        Args:
            appointment_id (str): Unique identifier for the appointment.

        Returns:
            dict: {
                "success": True,
                "data": AppointmentInfo  # if appointment exists
            }
            or
            {
                "success": False,
                "error": str  # description of error, e.g., appointment not found
            }

        Constraints:
            - Appointment must exist in system.
            - No additional access control enforced here.
        """
        appointment = self.appointments.get(appointment_id)
        if not appointment:
            return { "success": False, "error": "Appointment not found" }
        return { "success": True, "data": appointment }

    def get_provider_info(self, provider_id: str) -> dict:
        """
        Retrieve provider details (name, specialization, contact info) by provider_id.

        Args:
            provider_id (str): The ID of the provider to look up.

        Returns:
            dict: {
                "success": True,
                "data": ProviderInfo  # Contains name, specialization, contact_info, etc.
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure, e.g. provider not found
            }

        Constraints:
            - provider_id must exist in the system.
            - No specific access control required for provider info query.
        """
        provider_info = self.providers.get(provider_id)
        if provider_info is None:
            return { "success": False, "error": "Provider not found" }

        return { "success": True, "data": provider_info }

    def get_medical_records_by_patient(self, patient_id: str) -> dict:
        """
        List all medical records uploaded by or related to a patient.

        Args:
            patient_id (str): Unique identifier for the patient.

        Returns:
            dict:
                - On success:
                    {
                        "success": True,
                        "data": List[MedicalRecordInfo]  # List of medical records, may be empty
                    }
                - On failure:
                    {
                        "success": False,
                        "error": str  # Reason for failure
                    }

        Constraints:
            - The patient_id must exist in the portal.
        """
        if patient_id not in self.patients:
            return {"success": False, "error": "Patient does not exist"}

        records = [
            record for record in self.medical_records.values()
            if record["patient_id"] == patient_id
        ]
        return {"success": True, "data": records}

    def get_medical_records_for_appointment(self, appointment_id: str) -> dict:
        """
        List all medical records associated with the specified appointment.

        Args:
            appointment_id (str): The unique identifier of the appointment.

        Returns:
            dict: {
                "success": True,
                "data": List[MedicalRecordInfo]  # list may be empty if no records
            }
            or
            {
                "success": False,
                "error": str  # reason for error (e.g., appointment not found)
            }

        Constraints:
            - The appointment_id must exist in the system.
            - The MedicalRecord must be associated with the appointment by 'appointment_id' attribute.
              (Assumes MedicalRecordInfo contains 'appointment_id')
        """
        if appointment_id not in self.appointments:
            return { "success": False, "error": "Appointment not found" }

        # Some versions may not have 'appointment_id' in MedicalRecordInfo
        result = [
            record for record in self.medical_records.values()
            if record.get("appointment_id") == appointment_id
        ]

        return { "success": True, "data": result }

    def check_file_type_and_size_validity(self, file_type: str, file_size: int) -> dict:
        """
        Check if the proposed medical file's type and size meet the current upload restrictions.

        Args:
            file_type (str): File type/extension (e.g., 'pdf', 'jpg', 'docx').
            file_size (int): Size in bytes.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "valid": bool,
                    "reason": str (if not valid)
                }
            }

        Constraints:
            - Allowed file types: pdf, jpg, png, docx.
            - Maximum allowed file size: 10MB (10,000,000 bytes).
            - file_type must be a non-empty string.
            - file_size must be non-negative.
        """
        allowed_types = {"pdf", "jpg", "png", "docx"}
        max_size_bytes = 10_000_000  # 10 MB

        # Validate file_type
        if not file_type or not isinstance(file_type, str):
            return {
                "success": True,
                "data": {
                    "valid": False,
                    "reason": "File type is required and must be a string."
                }
            }
        file_type = file_type.lower()
        if file_type not in allowed_types:
            return {
                "success": True,
                "data": {
                    "valid": False,
                    "reason": f"File type '{file_type}' is not permitted. Allowed: {', '.join(sorted(allowed_types))}."
                }
            }
        # Validate file_size
        if not isinstance(file_size, int) or file_size < 0:
            return {
                "success": True,
                "data": {
                    "valid": False,
                    "reason": "File size must be a non-negative integer."
                }
            }
        if file_size > max_size_bytes:
            return {
                "success": True,
                "data": {
                    "valid": False,
                    "reason": f"File size {file_size} bytes exceeds the maximum allowed ({max_size_bytes} bytes)."
                }
            }
        # Valid!
        return {
            "success": True,
            "data": {
                "valid": True
            }
        }

    def check_record_access_permission(self, record_id: str, user_id: str, user_type: str) -> dict:
        """
        Determines if a patient or provider can access/view the specified medical record.

        Args:
            record_id (str): The ID of the medical record.
            user_id (str): The ID of the requesting patient or provider.
            user_type (str): Type of user, either 'patient' or 'provider'.

        Returns:
            dict: 
                {
                    "success": True,
                    "data": bool  # True if access is permitted, False otherwise
                }
                or
                {
                    "success": False,
                    "error": str  # Description of the error circumstance
                }

        Constraints:
            - The medical record specified by record_id must exist.
            - User must exist and match user_type.
            - Access determined by the record's access_permission and user association.
        """
        if record_id not in self.medical_records:
            return {"success": False, "error": "Medical record not found"}

        record = self.medical_records[record_id]
        permission = record.get("access_permission", "")

        if user_type == "patient":
            if user_id not in self.patients:
                return {"success": False, "error": "Patient not found"}
            # The patient can only access their own records
            if user_id != record["patient_id"]:
                return {"success": True, "data": False}
            # If permission allows patient viewing
            allowed = permission in ["private", "shared_patient_provider", "patient_view"]
            return {"success": True, "data": allowed}
        elif user_type == "provider":
            if user_id not in self.providers:
                return {"success": False, "error": "Provider not found"}
            # Assume provider can access "shared_patient_provider" or "provider_view"
            allowed = permission in ["shared_patient_provider", "provider_view"]
            return {"success": True, "data": allowed}
        else:
            return {"success": False, "error": "Invalid user type"}

    def get_record_details(self, record_id: str) -> dict:
        """
        Retrieve details about a single medical record by record_id.

        Args:
            record_id (str): Unique identifier of the medical record.

        Returns:
            dict: {
                "success": True,
                "data": MedicalRecordInfo,  # All metadata about the record
            }
            or
            {
                "success": False,
                "error": str  # Error message if record not found
            }

        Constraints:
            - The record_id must exist in the medical_records.
            - No permission checking performed in this method (for internal lookup).
        """
        record = self.medical_records.get(record_id)
        if not record:
            return { "success": False, "error": "Medical record not found" }

        return { "success": True, "data": record }

    def upload_medical_record(
        self,
        patient_id: str,
        appointment_id: str,
        file_path: str,
        file_type: str,
        file_size: int,
        upload_datetime: str,
        description: str,
        access_permission: str
    ) -> dict:
        """
        Upload a new medical file for a patient for a given appointment.
        Enforces file type and size restrictions and sets initial access permissions.

        Args:
            patient_id (str): Patient uploading the record.
            appointment_id (str): Associated appointment.
            file_path (str): Path to uploaded file.
            file_type (str): The file extension/type.
            file_size (int): File size in bytes.
            upload_datetime (str): Upload timestamp (ISO string).
            description (str): Optional metadata for the record.
            access_permission (str): Initial access permission string.

        Returns:
            dict:
                success (bool): Whether upload succeeded.
                message (str): Description of success.
                or
                error (str): Reason for failure.

        Constraints:
            - Patient must exist.
            - Appointment must exist and belong to patient.
            - Only authorized patients can upload for their own appointments.
            - File type/size must be valid.
            - Medical record must be associated with patient and appointment.
        """
        # Patient existence/auth check
        patient = self.patients.get(patient_id)
        if not patient:
            return { "success": False, "error": "Patient does not exist." }

        appointment = self.appointments.get(appointment_id)
        if not appointment:
            return { "success": False, "error": "Appointment does not exist." }
        if appointment["patient_id"] != patient_id:
            return { "success": False, "error": "Appointment does not belong to patient, cannot upload." }

        # File type and size validity (assume helper is implemented)
        file_check_result = self.check_file_type_and_size_validity(file_type=file_type, file_size=file_size)
        if not file_check_result.get("success", False):
            return { "success": False, "error": f"File type/size invalid: {file_check_result.get('error', 'Unknown')}" }

        # Create a unique record_id
        record_id = str(uuid.uuid4())
        if record_id in self.medical_records:
            # Extremely unlikely, but handle
            return { "success": False, "error": "Record ID collision, try again." }

        # Store MedicalRecordInfo
        record_info = MedicalRecordInfo(
            record_id=record_id,
            patient_id=patient_id,
            file_path=file_path,
            file_type=file_type,
            upload_datetime=upload_datetime,
            description=description,
            access_permission=access_permission
        )
        self.medical_records[record_id] = record_info

        # Here we could (optionally) store a mapping: appointment_id -> [record_id], but the schema doesn't enforce.

        return { "success": True, "message": "Medical record uploaded and associated." }

    def associate_record_with_appointment(self, record_id: str, appointment_id: str) -> dict:
        """
        Links an existing medical record to a specific appointment, if not already associated.

        Args:
            record_id (str): The ID of the medical record to be linked.
            appointment_id (str): The ID of the appointment to link to.

        Returns:
            dict: {
                "success": True,
                "message": "Medical record linked to appointment successfully."
            }
            or
            {
                "success": False,
                "error": "<reason for failure>"
            }

        Constraints:
            - Both record and appointment must exist.
            - Only link records and appointments for the same patient.
            - Record can't be associated with multiple appointments.
            - Links must be unique.
        """
        # Ensure the mapping exists for associations if not yet created.
        if not hasattr(self, "record_appointment_links"):
            self.record_appointment_links = {}

        if record_id not in self.medical_records:
            return { "success": False, "error": "Medical record not found." }
        if appointment_id not in self.appointments:
            return { "success": False, "error": "Appointment not found." }

        record = self.medical_records[record_id]
        appointment = self.appointments[appointment_id]

        # Confirm patient match.
        if record["patient_id"] != appointment["patient_id"]:
            return { "success": False, "error": "Patient mismatch: record and appointment belong to different patients." }

        # Already associated?
        if record_id in self.record_appointment_links:
            if self.record_appointment_links[record_id] == appointment_id:
                return { "success": False, "error": "Record already linked to this appointment." }
            else:
                return { "success": False, "error": "Record already linked to another appointment." }

        # Link the record.
        self.record_appointment_links[record_id] = appointment_id
        return { "success": True, "message": "Medical record linked to appointment successfully." }

    def update_record_access_permission(self, record_id: str, new_permission: str, requester_id: str) -> dict:
        """
        Modify the access_permission of a specified medical record.

        Args:
            record_id (str): The unique identifier of the medical record.
            new_permission (str): The new permission string to be set.
            requester_id (str): The patient or provider initiating the change, for authorization.

        Returns:
            dict: {
                "success": True,
                "message": "Access permission updated successfully"
            }
            or
            {
                "success": False,
                "error": str  # Description of the error
            }

        Constraints:
            - Only authorized patients (owners of the record) or authorized providers/admins can update the permission.
            - record_id must exist.
            - new_permission should be a valid permission string.
        """
        # Check that the medical record exists
        record = self.medical_records.get(record_id)
        if record is None:
            return { "success": False, "error": "Medical record not found" }

        # Permission validity check (example: restrict to a set of allowed values)
        allowed_permissions = {"patient_only", "provider_read", "provider_write", "clinic_read"}
        if new_permission not in allowed_permissions:
            return { "success": False, "error": "Invalid permission value" }

        # Authorization logic: only patient owner or privileged provider/admin can do this
        patient_id = record["patient_id"]
        is_patient_owner = requester_id == patient_id
        is_provider = requester_id in self.providers
        # You may extend with admin/staff logic, but basic check here:
        if not (is_patient_owner or is_provider):
            return { "success": False, "error": "Requester not authorized to update permission" }

        # Perform the update
        record["access_permission"] = new_permission

        return { "success": True, "message": "Access permission updated successfully" }

    def delete_medical_record(self, record_id: str, requester_id: str) -> dict:
        """
        Removes a medical record from the system, enforcing access/restriction checks.

        Args:
            record_id (str): Unique identifier for the medical record to delete.
            requester_id (str): Patient (or provider) requesting the operation.

        Returns:
            dict: {
                "success": True,
                "message": "Medical record deleted successfully"
            }
            or
            {
                "success": False,
                "error": <str describing problem>
            }

        Constraints:
        - Record must exist.
        - Only the record's owning patient can delete their own medical record.
        - All references in the system (appointments, etc.) should be considered if applicable.
        """
        record = self.medical_records.get(record_id)
        if record is None:
            return {"success": False, "error": "Medical record does not exist"}

        if requester_id != record["patient_id"]:
            return {"success": False, "error": "Access denied: only the record-owner patient may delete."}

        # Delete medical record
        del self.medical_records[record_id]

        # Optionally: remove links from appointments or other objects (if needed)
        # This environment associates records with appointments via 'associate_record_with_appointment'
        # If there are such links, they should be cleaned up, but not specified here.

        return {"success": True, "message": "Medical record deleted successfully"}

    def update_medical_record_metadata(
        self,
        record_id: str,
        description: str = None,
        access_permission: str = None
    ) -> dict:
        """
        Edit metadata of an existing medical record (e.g., update description, access_permission).

        Args:
            record_id (str): Unique medical record identifier.
            description (str, optional): New description for the record.
            access_permission (str, optional): New access permission string.

        Returns:
            dict: {
                "success": True,
                "message": "Medical record metadata updated successfully"
            }
            or
            {
                "success": False,
                "error": "reason"
            }

        Constraints:
            - The record must exist.
            - Only allowed fields (description, access_permission) will be updated.
            - At least one field must be provided to update.
        """
        record = self.medical_records.get(record_id)
        if not record:
            return { "success": False, "error": "Medical record not found" }

        updated = False

        # Only update allowable fields
        if description is not None:
            if isinstance(description, str):
                record["description"] = description
                updated = True
            else:
                return { "success": False, "error": "Description must be a string" }
        if access_permission is not None:
            if isinstance(access_permission, str):
                record["access_permission"] = access_permission
                updated = True
            else:
                return { "success": False, "error": "Access permission must be a string" }

        if not updated:
            return { "success": False, "error": "No valid metadata fields provided to update" }

        return { "success": True, "message": "Medical record metadata updated successfully" }

    def detach_record_from_appointment(self, record_id: str, appointment_id: str) -> dict:
        """
        Removes the association between a medical record (record_id) and a specific appointment (appointment_id).

        Args:
            record_id (str): The unique identifier of the medical record.
            appointment_id (str): The unique identifier of the appointment.

        Returns:
            dict: {
                "success": True,
                "message": "Medical record detached from appointment."
            }
            OR
            dict: {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - Only authorized actions are allowed (authorization is assumed here).
            - Both record and appointment must exist.
            - The medical record must actually be associated with the given appointment.
        """
        # Validate existence of record
        record = self.medical_records.get(record_id)
        if record is None:
            return { "success": False, "error": "Medical record does not exist." }

        # Validate existence of appointment
        appointment = self.appointments.get(appointment_id)
        if appointment is None:
            return { "success": False, "error": "Appointment does not exist." }

        # The association may be represented by an 'appointment_id' field in the record (even if not in schema above)
        # If not present, return error
        if "appointment_id" not in record:
            return { "success": False, "error": "Medical record association to appointment is not tracked in the schema." }

        if record["appointment_id"] != appointment_id:
            return { "success": False, "error": "Medical record is not associated with the specified appointment." }

        # Remove association
        record["appointment_id"] = ""
        self.medical_records[record_id] = record  # Update the record

        return { "success": True, "message": "Medical record detached from appointment." }

