def check_file_type_and_size_validity(self, file_type: str, file_size: int) -> dict:
    """
    Check if the proposed medical file's type and size meet the current upload restrictions.

    Args:
        file_type (str): File type/extension (e.g., 'pdf', 'jpg', 'docx').
        file_size (int): Size in bytes.

    Returns:
        dict: {
            "success": True,
            "data": {
                "valid": bool,
                "reason": str (if not valid)
            }
        }

    Constraints:
        - Allowed file types: pdf, jpg, png, docx.
        - Maximum allowed file size: 10MB (10,000,000 bytes).
        - file_type must be a non-empty string.
        - file_size must be non-negative.
    """
    allowed_types = {"pdf", "jpg", "png", "docx"}
    max_size_bytes = 10_000_000  # 10 MB

    # Validate file_type
    if not file_type or not isinstance(file_type, str):
        return {
            "success": True,
            "data": {
                "valid": False,
                "reason": "File type is required and must be a string."
            }
        }
    file_type = file_type.lower()
    if file_type not in allowed_types:
        return {
            "success": True,
            "data": {
                "valid": False,
                "reason": f"File type '{file_type}' is not permitted. Allowed: {', '.join(sorted(allowed_types))}."
            }
        }
    # Validate file_size
    if not isinstance(file_size, int) or file_size < 0:
        return {
            "success": True,
            "data": {
                "valid": False,
                "reason": "File size must be a non-negative integer."
            }
        }
    if file_size > max_size_bytes:
        return {
            "success": True,
            "data": {
                "valid": False,
                "reason": f"File size {file_size} bytes exceeds the maximum allowed ({max_size_bytes} bytes)."
            }
        }
    # Valid!
    return {
        "success": True,
        "data": {
            "valid": True
        }
    }

