from typing import Dict, TypedDict



class ProductInfo(TypedDict):
    # Represents items offered on the platform (product entity)
    product_id: str
    name: str
    category: str
    description: str

class ReviewInfo(TypedDict):
    # Represents consumer feedback for products (review entity)
    review_id: str
    product_id: str
    user_id: str
    rating: int
    review_text: str
    timestamp: str
    moderation_status: str

class UserInfo(TypedDict):
    # Represents the author of reviews (user entity)
    user_id: str
    username: str
    account_status: str

class EcommerceProductReviewSystem:
    def __init__(self, init_config: dict):
        """
        Environment for e-commerce product review management.
        init_config: external initializer (not implemented here).
        """

        # Products: {product_id: ProductInfo}
        self.products: Dict[str, ProductInfo] = {}

        # Reviews: {review_id: ReviewInfo}
        self.reviews: Dict[str, ReviewInfo] = {}

        # Users: {user_id: UserInfo}
        self.users: Dict[str, UserInfo] = {}

        # Constraints:
        # - Each review must be linked to an existing product via product_id.
        # - Reviews can only be retrieved for products that exist in the system.
        # - Reviews may be subject to moderation before being visible in queries (moderation_status).
        # - Users may be limited to one review per product.

        self.init_config = init_config

    def get_product_by_id(self, product_id: str) -> dict:
        """
        Retrieve product details using its unique product_id.

        Args:
            product_id (str): The identifier for the product to be retrieved.

        Returns:
            dict:
                - On success:
                    { "success": True, "data": ProductInfo }
                - On failure:
                    { "success": False, "error": "Product not found" }

        Constraints:
            - The product must exist in the system.
        """
        product = self.products.get(product_id)
        if product is None:
            return { "success": False, "error": "Product not found" }
        return { "success": True, "data": product }

    def list_all_products(self) -> dict:
        """
        Retrieve the full list of products in the system.

        Args:
            None

        Returns:
            dict: {
                "success": True,
                "data": List[ProductInfo]  # List of all products (possibly empty)
            }

        Constraints:
            - No input constraints for this operation.
            - If no products exist, the returned list is empty but still a success.
        """
        product_list = list(self.products.values())
        return { "success": True, "data": product_list }

    def get_reviews_for_product(self, product_id: str) -> dict:
        """
        Retrieve all reviews attached to a given product by product_id.
        Only reviews with appropriate moderation_status ("approved") are returned.

        Args:
            product_id (str): The product identifier to fetch reviews for.

        Returns:
            dict:
              - Success: { "success": True, "data": List[ReviewInfo] }
              - Failure: { "success": False, "error": "Product does not exist." }

        Constraints:
            - Product must exist in the system.
            - Only reviews with moderation_status=="approved" are returned.
        """
        if product_id not in self.products:
            return { "success": False, "error": "Product does not exist." }

        # Return only reviews for the product with status "approved"
        reviews = [
            review for review in self.reviews.values()
            if review["product_id"] == product_id and review.get("moderation_status") == "approved"
        ]

        return { "success": True, "data": reviews }

    def get_reviews_for_product_by_status(self, product_id: str, moderation_status: str) -> dict:
        """
        Retrieve all reviews for a product, filtered by the provided moderation_status.

        Args:
            product_id (str): Unique identifier for the product.
            moderation_status (str): Only reviews with this moderation status will be returned (e.g. "approved", "pending").

        Returns:
            dict: 
                If product exists:
                    {
                        "success": True,
                        "data": List[ReviewInfo]  # May be empty if no matching reviews.
                    }
                If product does not exist:
                    {
                        "success": False,
                        "error": "Product does not exist"
                    }

        Constraints:
            - Only reviews for products actually present are allowed.
            - Only reviews with matching moderation_status will be returned.
        """
        if product_id not in self.products:
            return { "success": False, "error": "Product does not exist" }

        filtered_reviews = [
            review for review in self.reviews.values()
            if review["product_id"] == product_id and review["moderation_status"] == moderation_status
        ]
        return { "success": True, "data": filtered_reviews }

    def get_review_by_id(self, review_id: str) -> dict:
        """
        Retrieve details for a specific review given its review_id.

        Args:
            review_id (str): Unique identifier of the review to retrieve.

        Returns:
            dict: 
                Success: {
                    "success": True,
                    "data": ReviewInfo  # full info of the matched review
                }
                Failure: {
                    "success": False,
                    "error": "Review not found"
                }

        Constraints:
            - Review with matching review_id must exist in the system.
            - No moderation_status filtering is applied for direct lookup.
        """
        review = self.reviews.get(review_id)
        if not review:
            return { "success": False, "error": "Review not found" }
        return { "success": True, "data": review }

    def get_user_by_id(self, user_id: str) -> dict:
        """
        Retrieve user details using their user_id.

        Args:
            user_id (str): Unique identifier for the user.

        Returns:
            dict:
                On success:
                    {
                        "success": True,
                        "data": UserInfo  # User's details
                    }
                On failure:
                    {
                        "success": False,
                        "error": str  # Reason (e.g., 'User not found')
                    }

        Constraints:
            - The user_id must exist in the system.
        """
        user_info = self.users.get(user_id)
        if user_info is None:
            return { "success": False, "error": "User not found" }
        return { "success": True, "data": user_info }

    def get_reviews_by_user(self, user_id: str) -> dict:
        """
        List all reviews authored by the specified user.

        Args:
            user_id (str): The ID of the user for whom to retrieve reviews.

        Returns:
            dict: 
                - On success: {
                    "success": True,
                    "data": List[ReviewInfo]  # list of reviews (can be empty)
                }
                - On failure: {
                    "success": False,
                    "error": str  # reason for failure, e.g. user does not exist
                }

        Constraints:
            - The user_id must exist in the system.
            - All returned reviews must have 'user_id' equal to the input.
        """
        if user_id not in self.users:
            return { "success": False, "error": "User does not exist" }

        reviews_by_user = [
            review for review in self.reviews.values()
            if review["user_id"] == user_id
        ]
        return { "success": True, "data": reviews_by_user }

    def has_user_reviewed_product(self, user_id: str, product_id: str) -> dict:
        """
        Check whether the given user has already reviewed the specified product.

        Args:
            user_id (str): Unique identifier of the user.
            product_id (str): Unique identifier of the product.

        Returns:
            dict: {
                "success": True,
                "data": bool  # True if the user has a review for the product, else False.
            } or {
                "success": False,
                "error": str  # Description of the error.
            }

        Constraints:
            - The user and product must exist.
        """
        if product_id not in self.products:
            return {"success": False, "error": "Product does not exist"}
        if user_id not in self.users:
            return {"success": False, "error": "User does not exist"}

        found = any(
            review_info["user_id"] == user_id and review_info["product_id"] == product_id
            for review_info in self.reviews.values()
        )
        return {"success": True, "data": found}

    def add_review(
        self,
        product_id: str,
        user_id: str,
        rating: int,
        review_text: str,
        timestamp: str,
        moderation_status: str
    ) -> dict:
        """
        Submit a new review for a product by a user.

        Enforces constraint: one review per product per user.

        Args:
            product_id (str): Target product's unique ID.
            user_id (str): User's unique ID.
            rating (int): Numerical rating for the product.
            review_text (str): The actual feedback text.
            timestamp (str): ISO string or similar representation of review time.
            moderation_status (str): Initial moderation status for the review.

        Returns:
            dict: {
                "success": True,
                "message": "Review added",
                "review_id": <str>
            }
            or
            {
                "success": False,
                "error": "Product/User doesn't exist, or user already reviewed product"
            }

        Constraints:
            - Product must exist.
            - User must exist.
            - One review per product per user.
            - Unique review_id per review.
        """

        if product_id not in self.products:
            return { "success": False, "error": "Product does not exist" }

        if user_id not in self.users:
            return { "success": False, "error": "User does not exist" }

        # Enforce one review per product/user
        for review in self.reviews.values():
            if review["product_id"] == product_id and review["user_id"] == user_id:
                return { "success": False, "error": "User has already reviewed this product" }

        # Generate unique review_id (simple increment or UUID-like)
        base_id = f"{product_id}-{user_id}"
        suffix = 1
        review_id = base_id
        while review_id in self.reviews:
            suffix += 1
            review_id = f"{base_id}-{suffix}"

        # Construct review info
        review_info: ReviewInfo = {
            "review_id": review_id,
            "product_id": product_id,
            "user_id": user_id,
            "rating": rating,
            "review_text": review_text,
            "timestamp": timestamp,
            "moderation_status": moderation_status
        }

        self.reviews[review_id] = review_info

        return {
            "success": True,
            "message": "Review added",
            "review_id": review_id
        }

    def update_review_moderation_status(self, review_id: str, new_status: str) -> dict:
        """
        Change the moderation_status of a review (e.g., approve or reject).

        Args:
            review_id (str): Unique identifier of the review to update.
            new_status (str): The target moderation status ("pending", "approved", "rejected").

        Returns:
            dict: 
                - On success: { "success": True, "message": "Moderation status updated successfully" }
                - On failure: { "success": False, "error": <reason> }

        Constraints:
            - The provided review_id must exist in self.reviews.
            - new_status must be one of ["pending", "approved", "rejected"].
        """
        valid_statuses = ["pending", "approved", "rejected"]

        if review_id not in self.reviews:
            return { "success": False, "error": "Review not found" }

        if new_status not in valid_statuses:
            return { "success": False, "error": f"Invalid moderation status '{new_status}'" }

        self.reviews[review_id]["moderation_status"] = new_status
        return { "success": True, "message": "Moderation status updated successfully" }

    def edit_review(
        self,
        review_id: str,
        review_text: str = None,
        rating: int = None,
        timestamp: str = None,
        moderation_status: str = None
    ) -> dict:
        """
        Update the content, rating, timestamp, or other editable fields of a submitted review.

        Args:
            review_id (str): Review to update.
            review_text (str, optional): New review text.
            rating (int, optional): New rating.
            timestamp (str, optional): New modification timestamp.
            moderation_status (str, optional): Optionally update moderation status.

        Returns:
            dict: {
                "success": True,
                "message": "Review updated successfully."
            }
            or
            dict: {
                "success": False,
                "error": str
            }

        Constraints:
            - The review must exist.
            - Only specified fields will be updated.
            - Review linkage to user/product cannot be changed.
        """
        review = self.reviews.get(review_id)
        if not review:
            return {"success": False, "error": "Review does not exist."}

        updated = False

        if review_text is not None:
            review['review_text'] = review_text
            updated = True
        if rating is not None:
            if not isinstance(rating, int) or rating < 1 or rating > 5:
                return {"success": False, "error": "Rating must be an integer between 1 and 5."}
            review['rating'] = rating
            updated = True
        if timestamp is not None:
            review['timestamp'] = timestamp
            updated = True
        if moderation_status is not None:
            review['moderation_status'] = moderation_status
            updated = True

        if not updated:
            return {"success": False, "error": "No valid fields were provided for update."}

        self.reviews[review_id] = review
        return {"success": True, "message": "Review updated successfully."}

    def delete_review(self, review_id: str) -> dict:
        """
        Remove a review from the system.

        Args:
            review_id (str): Unique identifier of the review to remove.

        Returns:
            dict: 
                If successful: {
                    "success": True,
                    "message": "Review <review_id> deleted successfully."
                }
                If not found: {
                    "success": False,
                    "error": "Review does not exist."
                }

        Constraints:
            - The review must exist in the system.
            - Other constraints such as moderation status do not block deletion.
        """
        if review_id not in self.reviews:
            return {"success": False, "error": "Review does not exist."}

        del self.reviews[review_id]

        return {
            "success": True,
            "message": f"Review {review_id} deleted successfully."
        }

    def add_product(self, product_id: str, name: str, category: str, description: str) -> dict:
        """
        Create a new product entry in the system.

        Args:
            product_id (str): Unique product identifier.
            name (str): Name of the product.
            category (str): Product category.
            description (str): Description of the product.

        Returns:
            dict: {
                "success": True,
                "message": "Product <product_id> added successfully."
            }
            or
            {
                "success": False,
                "error": str  # Failure reason (e.g., duplicate product_id)
            }

        Constraints:
            - product_id must be unique in the system.
        """
        if product_id in self.products:
            return { "success": False, "error": "Product ID already exists." }

        self.products[product_id] = {
            "product_id": product_id,
            "name": name,
            "category": category,
            "description": description
        }

        return { "success": True, "message": f"Product {product_id} added successfully." }

    def delete_product(self, product_id: str) -> dict:
        """
        Remove a product and all reviews linked to it from the system.

        Args:
            product_id (str): The unique identifier of the product to delete.

        Returns:
            dict: {
                "success": True,
                "message": "Product <product_id> and <N> linked reviews deleted"
            }
            or
            {
                "success": False,
                "error": "Product does not exist"
            }

        Constraints:
            - Product must exist in the system.
            - All reviews linked to the product are removed to maintain referential integrity.
        """
        if product_id not in self.products:
            return { "success": False, "error": "Product does not exist" }

        # Delete the product
        del self.products[product_id]

        # Find and delete all linked reviews
        reviews_to_delete = [review_id for review_id, rinfo in self.reviews.items()
                             if rinfo["product_id"] == product_id]
        for review_id in reviews_to_delete:
            del self.reviews[review_id]

        return {
            "success": True,
            "message": f"Product {product_id} and {len(reviews_to_delete)} linked reviews deleted"
        }

    def add_user(self, user_id: str, username: str, account_status: str) -> dict:
        """
        Register a new user in the system.

        Args:
            user_id (str): User's unique identifier.
            username (str): Username for the user.
            account_status (str): Initial account state ('active', 'pending', etc.).

        Returns:
            dict: 
                If success:
                    { "success": True, "message": "User <user_id> successfully added." }
                If failure:
                    { "success": False, "error": "reason" }

        Constraints:
            - user_id must be unique in self.users (cannot already exist).
        """
        if not user_id or not username or not account_status:
            return { "success": False, "error": "Missing required parameters." }

        if user_id in self.users:
            return { "success": False, "error": f"User ID '{user_id}' already exists." }

        self.users[user_id] = {
            "user_id": user_id,
            "username": username,
            "account_status": account_status
        }

        return { "success": True, "message": f"User '{user_id}' successfully added." }

    def delete_user(self, user_id: str) -> dict:
        """
        Remove a user and all their reviews from the system.

        Args:
            user_id (str): The ID of the user to remove.

        Returns:
            dict: {
                "success": True,
                "message": "User <user_id> and all their reviews have been deleted."
            }
            or
            {
                "success": False,
                "error": "User does not exist."
            }

        Constraints:
            - User must exist in the system to be deleted.
            - All reviews authored by the user must be deleted.
        """
        if user_id not in self.users:
            return { "success": False, "error": "User does not exist." }

        # Delete the user's reviews
        review_ids_to_delete = [
            review_id for review_id, review in self.reviews.items()
            if review["user_id"] == user_id
        ]
        for review_id in review_ids_to_delete:
            del self.reviews[review_id]

        # Delete the user
        del self.users[user_id]

        return {
            "success": True,
            "message": f"User {user_id} and all their reviews have been deleted."
        }

