def delete_user(self, user_id: str) -> dict:
    """
    Remove a user and all their reviews from the system.

    Args:
        user_id (str): The ID of the user to remove.

    Returns:
        dict: {
            "success": True,
            "message": "User <user_id> and all their reviews have been deleted."
        }
        or
        {
            "success": False,
            "error": "User does not exist."
        }

    Constraints:
        - User must exist in the system to be deleted.
        - All reviews authored by the user must be deleted.
    """
    if user_id not in self.users:
        return { "success": False, "error": "User does not exist." }

    # Delete the user's reviews
    review_ids_to_delete = [
        review_id for review_id, review in self.reviews.items()
        if review["user_id"] == user_id
    ]
    for review_id in review_ids_to_delete:
        del self.reviews[review_id]

    # Delete the user
    del self.users[user_id]

    return {
        "success": True,
        "message": f"User {user_id} and all their reviews have been deleted."
    }

