class OnlineSupportGroupPlatform:
    def __init__(self, init_config: dict):
        # Users: user_id → UserInfo
        self.users: Dict[str, UserInfo] = {}

        # Support groups: group_id → SupportGroupInfo
        self.groups: Dict[str, SupportGroupInfo] = {}

        # Memberships: membership_id → MembershipInfo
        self.memberships: Dict[str, MembershipInfo] = {}

        # Journal entries: entry_id → JournalEntryInfo
        self.journal_entries: Dict[str, JournalEntryInfo] = {}

        # Discussion threads: thread_id → DiscussionThreadInfo
        self.threads: Dict[str, DiscussionThreadInfo] = {}

        # --- Constraints/Rules ---
        # 1. Only users who are members of a support group may share journal entries within that group.
        # 2. Journal entry visibility is controlled by user settings (private vs group-shared).
        # 3. Group membership status (active, pending, removed) determines access rights to group content.
        # 4. Discussion threads must belong to a valid support group.

        self.init_config = init_config

    def get_user_info(self, user_id: str) -> dict:
        """
