            - User must exist in the system.
            - Includes all membership statuses.
        """
        if user_id not in self.users:
            return { "success": False, "error": "User does not exist" }

        # Find all memberships for this user
        user_memberships = [
            mem for mem in self.memberships.values()
            if mem.get("user_id") == user_id
        ]

        result = []
        for mem in user_memberships:
            group_id = mem.get("group_id")
            group_info = self.groups.get(group_id)
            if group_info:
                result.append({
                    "group_id": group_id,
                    "group_name": group_info.get("group_name", ""),
                    "membership_status": mem.get("membership_status", "")
                })

