        if group_id not in self.groups:
            return { "success": False, "error": "Support group does not exist" }

        # Find membership for the user/group combination
        found_membership = None
        for membership in self.memberships.values():
            # Membership _id may be different from user_id, so check both group and user
            if membership["group_id"] == group_id:
                # Link membership to user_id by matching user's membership entries
                # But MembershipInfo lacks 'user_id' in env spec, so likely membership _id == user_id
                # But that would prevent multi-group membership; perhaps env spec is ambiguous
                # Here, assume membership _id == user_id for user <=> group pair
                if membership["_id"] == user_id:
