            }
            or
            {
                "success": False,
                "error": str  # Reason (e.g. group not found)
            }

        Constraints:
            - group_id must reference an existing support group.
            - Returns all associated memberships (any status).
            - If a membership points to a missing user, returns entry with 'user_id' and membership_status only.
        """
        if group_id not in self.groups:
            return {"success": False, "error": "Support group does not exist"}

        members = []
        for m in self.memberships.values():
            if m["group_id"] == group_id:
                # Try to find matching user
                user_id = m["_id"].split(":")[0] if ":" in m["_id"] else m.get("user_id")  # Try to infer user_id
                user_info = self.users.get(user_id)
                entry = {
                    "membership_id": m["_id"],
                    "membership_status": m["membership_status"],
                    "join_date": m.get("join_date", ""),
                }
                if user_info:
                    entry.update(user_info)
                else:
                    entry["user_id"] = user_id if user_id else None
                members.append(entry)

        return {"success": True, "data": members}

    def list_journal_entries_by_user(self, user_id: str) -> dict:
        """
        Retrieve all journal entries authored by a particular user.

        Args:
            user_id (str): The unique identifier of the user.

        Returns:
            dict: {
                "success": True,
                "data": List[JournalEntryInfo],  # List of journal entries by this user (can be empty)
            }
            or
            {
                "success": False,
                "error": str  # Error message if user does not exist
            }

        Constraints:
            - The user must exist in the platform.
            - No membership or visibility filtering is applied; returns all entries authored by the user.
        """
        if user_id not in self.users:
            return { "success": False, "error": "User does not exist" }

        result = [
            entry for entry in self.journal_entries.values()
            if entry["user_id"] == user_id
        ]

        return { "success": True, "data": result }

    def list_journal_entries_in_group(self, group_id: str) -> dict:
        """
        Retrieve all journal entries shared within a specific support group.

        Args:
            group_id (str): The unique id of the support group.

        Returns:
            dict: {
                "success": True,
                "data": List[JournalEntryInfo],  # All entries with group_id and visibility 'group-shared'
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure, e.g. group does not exist
            }

        Constraints:
            - The group_id must exist in the system.
            - Only journal entries with group_id == group_id and visibility == "group-shared" are retrieved.
        """

        if group_id not in self.groups:
            return { "success": False, "error": "Group does not exist" }

        entries = [
            entry for entry in self.journal_entries.values()
            if entry["group_id"] == group_id and entry["visibility"] == "group-shared"
        ]

        return { "success": True, "data": entries }

    def get_journal_entry_info(self, entry_id: str) -> dict:
        """
        Retrieve full information and visibility details for a specific journal entry.

        Args:
            entry_id (str): Unique identifier of the journal entry.

        Returns:
            dict: On success,
                {
                    "success": True,
                    "data": JournalEntryInfo
                }
                On failure,
                {
                    "success": False,
                    "error": "Journal entry not found"
                }

        Constraints:
            - Simply retrieves existing entry info; does not require membership or visibility checking.
            - Entry must exist in self.journal_entries.
        """
        entry = self.journal_entries.get(entry_id)
        if not entry:
            return { "success": False, "error": "Journal entry not found" }
        return { "success": True, "data": entry }

    def get_discussion_threads_in_group(self, group_id: str) -> dict:
        """
        Retrieve all discussion threads that belong to a specified support group.

        Args:
            group_id (str): The ID of the support group.

        Returns:
            dict:
                - success: True and data: list of DiscussionThreadInfo (may be empty if no threads)
                - success: False and error: str (if the group does not exist)

        Constraints:
            - group_id must refer to a valid (existing) support group.
        """
        if group_id not in self.groups:
            return {"success": False, "error": "Support group does not exist"}

        result = [
            thread for thread in self.threads.values()
            if thread["group_id"] == group_id
        ]

        return {"success": True, "data": result}

    def get_thread_info(self, thread_id: str) -> dict:
        """
        Get key info for a discussion thread: title, creator, timestamp, and group.

        Args:
            thread_id (str): Unique identifier of the discussion thread.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "thread_id": str,
                    "title": str,
                    "created_by": str,
                    "timestamp": str,
                    "group_id": str
                }
            }
            or
            {
                "success": False,
                "error": str  # Reason, e.g. thread not found
            }

        Constraints:
            - The thread with the given thread_id must exist.
        """
        thread = self.threads.get(thread_id)
        if not thread:
            return { "success": False, "error": "Thread not found" }

        info = {
            "thread_id": thread["thread_id"],
            "title": thread["title"],
            "created_by": thread["created_by"],
            "timestamp": thread["timestamp"],
            "group_id": thread["group_id"]
        }
        return { "success": True, "data": info }


    def create_journal_entry(
        self,
        user_id: str,
        content: str,
        visibility: str,
        group_id: Optional[str] = None
    ) -> Dict:
        """
        Add a new journal entry for a user, with optional group association and specified visibility.

        Args:
            user_id (str): ID of the user creating the entry.
            content (str): Journal entry text/content.
            visibility (str): "private" or "group-shared".
            group_id (Optional[str]): If visibility is "group-shared", must specify valid group_id.

        Returns:
            dict: {
                "success": True,
                "message": "Journal entry created"
            }
            or
            {
                "success": False,
                "error": str
            }

        Constraints:
            - User must exist.
            - If visibility=="group-shared":
                - group_id must be provided and exist.
                - user must have active membership in group.
            - If visibility=="private":
                - group_id must be None.
            - entry_id must be unique.
        """
        # Validate user
        if user_id not in self.users:
            return { "success": False, "error": "User does not exist" }

        # Handle visibility and group logic
        if visibility not in ("private", "group-shared"):
            return { "success": False, "error": "Invalid visibility value" }

        if visibility == "private":
            if group_id is not None:
                return { "success": False, "error": "Private journal entries cannot have a group_id" }
        else:  # group-shared
            if not group_id:
                return { "success": False, "error": "group_id required for group-shared entry" }
            if group_id not in self.groups:
                return { "success": False, "error": "Support group does not exist" }
            # Check user active membership
            user_memberships = [
                m for m in self.memberships.values()
                if m["group_id"] == group_id and m.get("user_id", user_id) == user_id and m["membership_status"] == "active"
            ]
            # Note: MembershipInfo does not have user_id in spec, but needs to! We'll assume user_id is present.
            if not user_memberships:
                return { "success": False, "error": "User is not an active member of the group" }

        # Generate unique entry_id
        entry_id = str(uuid.uuid4())
        # Timestamp as ISO string
        timestamp = datetime.utcnow().isoformat()

        # Create journal entry
        self.journal_entries[entry_id] = {
            "entry_id": entry_id,
            "user_id": user_id,
            "group_id": group_id,
            "content": content,
            "timestamp": timestamp,
            "visibility": visibility
        }

        return { "success": True, "message": "Journal entry created" }

    def update_journal_entry_visibility(self, entry_id: str, new_visibility: str) -> dict:
        """
        Change a journal entry's visibility setting (private or group-shared).

        Args:
            entry_id (str): The ID of the journal entry to update.
            new_visibility (str): The desired visibility; must be "private" or "group-shared".

        Returns:
            dict: {
                "success": True,
                "message": "Journal entry visibility updated." | "Visibility already set."
            }
            or
            {
                "success": False,
                "error": str
            }

        Constraints:
            - Only allow "group-shared" if the entry is associated with a group *and*
              its author is an active member of that group.
            - Visibility must be "private" or "group-shared".
        """
        # Check entry exists
        entry = self.journal_entries.get(entry_id)
        if not entry:
            return {"success": False, "error": "Journal entry does not exist."}

        # Validate new_visibility
        if new_visibility not in ("private", "group-shared"):
            return {"success": False, "error": "Visibility must be 'private' or 'group-shared'."}

        # If already set to requested visibility, treat as success
        if entry["visibility"] == new_visibility:
            return {"success": True, "message": "Visibility already set."}

        # If requesting group-shared, validate group membership constraints
        if new_visibility == "group-shared":
            group_id = entry.get("group_id")
            user_id = entry["user_id"]
            if not group_id:
                return {"success": False, "error": "Journal entry is not associated with any group."}
            # Search for an active membership for the user in that group
            is_member = any(
                m["group_id"] == group_id and m["membership_status"] == "active" and m["_id"].startswith(user_id)
                for m in self.memberships.values()
                if m["_id"] and user_id in m["_id"]
            )
            if not is_member:
                return {"success": False, "error": "User is not an active member of the group."}

        # Change visibility
        entry["visibility"] = new_visibility

        return {"success": True, "message": "Journal entry visibility updated."}


    def create_support_group(self, group_name: str, description: str, privacy_setting: str) -> dict:
        """
        Establish a new support group.

        Args:
            group_name (str): Desired support group name (must be unique).
            description (str): Descriptive text for the support group.
            privacy_setting (str): Group privacy setting string (e.g. "public", "private").

        Returns:
            dict: On success:
                {
                    "success": True,
                    "message": "Support group created with group_id <id>"
                }
            On failure:
                {
                    "success": False,
                    "error": "reason for failure"
                }

        Constraints:
            - group_name must be unique among all support groups.
            - Group will be assigned a unique group_id internally.
        """
        # Check if a group with the same name already exists
        for group in self.groups.values():
            if group["group_name"].lower() == group_name.lower():
                return { "success": False, "error": "Group name already exists" }

        # Create unique group_id
        group_id = str(uuid.uuid4())

        # Add new group to groups dict
        new_group = {
            "group_id": group_id,
            "group_name": group_name,
            "description": description,
            "privacy_setting": privacy_setting
        }
        self.groups[group_id] = new_group

        return {
            "success": True,
            "message": f"Support group created with group_id {group_id}"
        }


    def add_membership_to_group(self, user_id: str, group_id: str) -> dict:
        """
        Adds or updates a membership for a user in a specified support group.

        Args:
            user_id (str): The ID of the user.
            group_id (str): The ID of the support group.

        Returns:
            dict: {
                "success": True,
                "message": str  # Description of the operation (added or updated),
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure (user/group not found),
            }

        Constraints:
            - User and group must exist.
            - Membership status will be set to 'active'.
            - If membership for user/group exists (any status), update to 'active', otherwise create a new record.
            - join_date is set to current date/time (ISO format).
        """
        # Check user exists
        if user_id not in self.users:
            return {"success": False, "error": "User does not exist."}
        # Check group exists
        if group_id not in self.groups:
            return {"success": False, "error": "Support group does not exist."}

        # Search for existing membership for this user/group
        existing_membership_id = None
        for membership_id, membership in self.memberships.items():
            # Let's assume _id in MembershipInfo is the identifier.
            if (membership.get("user_id") == user_id) and (membership.get("group_id") == group_id):
                existing_membership_id = membership_id
                break

        now_iso = datetime.utcnow().isoformat()

        if existing_membership_id is not None:
            membership = self.memberships[existing_membership_id]
            if membership["membership_status"] == "active":
                # Idempotent: already active
                membership["join_date"] = now_iso  # Update join date for 'active' again
                return {"success": True, "message": "Membership is already active; join date updated."}
            else:
                # Update status to active
                membership["membership_status"] = "active"
                membership["join_date"] = now_iso
                return {"success": True, "message": "Membership updated to active for user in group."}
        else:
            # Create unique membership ID (simple scheme: "user_id:group_id:ts")
            new_membership_id = f"{user_id}:{group_id}:{int(datetime.utcnow().timestamp())}"
            self.memberships[new_membership_id] = {
                "_id": new_membership_id,
                "user_id": user_id,
                "group_id": group_id,
                "membership_status": "active",
                "join_date": now_iso
            }
            return {"success": True, "message": "Membership added: user is now active in group."}

    def change_membership_status(self, membership_id: str, new_status: str) -> dict:
        """
        Update the status of a user's membership in a group.

        Args:
            membership_id (str): The ID of the membership record to update.
            new_status (str): The target status value ('active', 'pending', 'removed').

        Returns:
            dict: If successful: { "success": True, "message": "Membership status updated to <new_status>." }
                  If membership does not exist or status is invalid: { "success": False, "error": str }

        Constraints:
            - membership_id must exist in the environment.
            - new_status must be one of {"active", "pending", "removed"}.
            - The membership status will be updated in-place.
        """
        ALLOWED_STATUSES = {"active", "pending", "removed"}

        if membership_id not in self.memberships:
            return { "success": False, "error": "Membership not found." }

        if new_status not in ALLOWED_STATUSES:
            return { "success": False, "error": f"Status '{new_status}' is not valid. Allowed: {ALLOWED_STATUSES}" }

        self.memberships[membership_id]["membership_status"] = new_status

        return { "success": True, "message": f"Membership status updated to {new_status}." }


    def create_discussion_thread(
        self,
        group_id: str,
        title: str,
        created_by: str
    ) -> dict:
        """
        Start a new discussion thread within a valid support group.

        Args:
            group_id (str): The ID of the support group.
            title (str): The title of the discussion thread.
            created_by (str): The user ID who initiates the thread.

        Returns:
            dict:
                - On success: {"success": True, "message": "Discussion thread created in group <group_id>"}
                - On failure: {"success": False, "error": "<reason>"}

        Constraints:
            - The group_id must correspond to an existing group.
            - The created_by user must exist.
            - The thread_id must be unique (auto-generated).
            - title must be a non-empty string.
        """
        # Check group validity
        if group_id not in self.groups:
            return {"success": False, "error": "Support group does not exist"}

        # Check creator validity
        if created_by not in self.users:
            return {"success": False, "error": "User (created_by) does not exist"}

        if not isinstance(title, str) or not title.strip():
            return {"success": False, "error": "Thread title must be a non-empty string"}

        thread_id = str(uuid.uuid4())
        timestamp = str(time.time())

        thread_info = {
            "thread_id": thread_id,
            "group_id": group_id,
            "title": title.strip(),
            "created_by": created_by,
            "timestamp": timestamp
        }

        self.threads[thread_id] = thread_info

        return {
            "success": True,
            "message": f"Discussion thread created in group {group_id}"
        }

    def delete_journal_entry(self, entry_id: str) -> dict:
        """
        Remove a journal entry from the platform.

        Args:
            entry_id (str): The journal entry's unique identifier.

        Returns:
            dict: 
                On success:
                    { "success": True, "message": "Journal entry deleted." }
                On failure (entry not found):
                    { "success": False, "error": "Journal entry not found." }

        Constraints:
            - Only deletes if entry_id exists.
        """
        if entry_id not in self.journal_entries:
            return { "success": False, "error": "Journal entry not found." }
        del self.journal_entries[entry_id]
        return { "success": True, "message": "Journal entry deleted." }

    def delete_discussion_thread(self, thread_id: str) -> dict:
        """
        Remove a discussion thread from a group.

        Args:
            thread_id (str): The ID of the discussion thread to be deleted.

        Returns:
            dict: {
                "success": True,
                "message": "Discussion thread <thread_id> deleted."
            }
            OR
            {
                "success": False,
                "error": str  # Reason: thread does not exist, invalid group, etc.
            }

        Constraints:
            - The discussion thread must exist.
            - The thread must belong to a valid support group.
        """
        thread_info = self.threads.get(thread_id)
        if not thread_info:
            return { "success": False, "error": "Discussion thread does not exist." }
        group_id = thread_info.get("group_id")
        if not group_id or group_id not in self.groups:
            return { "success": False, "error": "Discussion thread's group is invalid or does not exist." }
        del self.threads[thread_id]
        return { "success": True, "message": f"Discussion thread {thread_id} deleted." }

    def update_journal_entry_content(self, entry_id: str, user_id: str, new_content: str) -> dict:
        """
        Modify the content of an existing journal entry.

        Args:
            entry_id (str): The journal entry to be modified.
            user_id (str): The user requesting the update (must be entry owner).
            new_content (str): Replacement content for the entry.

        Returns:
            dict: {
                "success": True,
                "message": "Journal entry content updated successfully"
            }
            or
            {
                "success": False,
                "error": "reason"
            }

        Constraints:
            - Journal entry must exist.
            - Only the owning user may update a journal entry.
            - Content must not be None.
            - Updates to timestamps are not required by rules, but may be performed for consistency.
        """
        entry = self.journal_entries.get(entry_id)
        if entry is None:
            return { "success": False, "error": "Journal entry not found" }
        if entry["user_id"] != user_id:
            return { "success": False, "error": "Permission denied: user does not own this journal entry" }
        if not isinstance(new_content, str) or new_content == "":
            return { "success": False, "error": "Content cannot be empty" }

        entry["content"] = new_content
        # Optionally update timestamp to now; assuming ISO format, standard practice
        entry["timestamp"] = datetime.utcnow().isoformat()

        return { "success": True, "message": "Journal entry content updated successfully" }

    def update_support_group_info(
        self, 
        group_id: str, 
        description: Optional[str] = None, 
        privacy_setting: Optional[str] = None
    ) -> dict:
        """
        Modify the description and/or privacy setting of a support group.

        Args:
            group_id (str): Identifier for the support group to update.
            description (Optional[str]): New description text, if update desired.
            privacy_setting (Optional[str]): New privacy setting, if update desired.

        Returns:
            dict: 
                On success:
                    {
                        "success": True,
                        "message": "Support group information updated."
                    }
                On error:
                    {
                        "success": False,
                        "error": "Support group not found."  # or
                        "error": "No update fields provided."
                    }
        Constraints:
            - Group must exist.
            - At least one of description or privacy_setting must be provided.
            - Only non-None fields are updated.
        """
        group = self.groups.get(group_id)
        if not group:
            return { "success": False, "error": "Support group not found." }

        if description is None and privacy_setting is None:
            return { "success": False, "error": "No update fields provided." }

        if description is not None:
            group['description'] = description
        if privacy_setting is not None:
            group['privacy_setting'] = privacy_setting

        return { "success": True, "message": "Support group information updated." }

