def check_membership_status(self, user_id: str, group_id: str) -> dict:
    """
    Query and validate a user's membership status in a specific support group.

    Args:
        user_id (str): ID of the user.
        group_id (str): ID of the support group.

    Returns:
        dict:
        - Success: { "success": True, "data": MembershipInfo }
        - Failure: { "success": False, "error": <reason> }

    Constraints:
        - User and group must exist.
        - Membership must exist for this user/group pair.
    """
    if user_id not in self.users:
        return { "success": False, "error": "User does not exist" }
    if group_id not in self.groups:
        return { "success": False, "error": "Support group does not exist" }

    # Find membership for the user/group combination
    found_membership = None
    for membership in self.memberships.values():
        # Membership _id may be different from user_id, so check both group and user
        if membership["group_id"] == group_id:
            # Link membership to user_id by matching user's membership entries
            # But MembershipInfo lacks 'user_id' in env spec, so likely membership _id == user_id
            # But that would prevent multi-group membership; perhaps env spec is ambiguous
            # Here, assume membership _id == user_id for user <=> group pair
            if membership["_id"] == user_id:
                found_membership = membership
                break

    if not found_membership:
        return { "success": False, "error": "Membership not found for user in this group" }

    return { "success": True, "data": found_membership }

