from typing import Dict, List, TypedDict



class PatientInfo(TypedDict):
    patient_id: str
    name: str
    date_of_birth: str
    demographic_info: dict
    medical_history: dict

class AllergyInfo(TypedDict):
    patient_id: str
    substance: str
    reaction_type: str
    confirmation_status: str
    date_recorded: str

class MedicationInfo(TypedDict):
    patient_id: str
    medication_name: str
    dosage: str
    start_date: str
    end_date: str
    prescribing_clinician: str

class LaboratoryResultInfo(TypedDict):
    patient_id: str
    test_type: str
    result_value: str
    date_conducted: str
    ordering_provider: str

class AuthorizedUserInfo(TypedDict):
    user_id: str
    name: str
    role: str
    access_rights: List[str]

class ElectronicHealthRecordSystem:
    def __init__(self, init_config: dict):
        # Patients: {patient_id: PatientInfo}
        self.patients: Dict[str, PatientInfo] = {}

        # Allergies: {patient_id: [AllergyInfo]}
        self.allergies: Dict[str, List[AllergyInfo]] = {}

        # Medications: {patient_id: [MedicationInfo]}
        self.medications: Dict[str, List[MedicationInfo]] = {}

        # Laboratory Results: {patient_id: [LaboratoryResultInfo]}
        self.laboratory_results: Dict[str, List[LaboratoryResultInfo]] = {}

        # Authorized users: {user_id: AuthorizedUserInfo}
        self.authorized_users: Dict[str, AuthorizedUserInfo] = {}

        # Constraints:
        # - Only authorized users may view or modify patient health records.
        # - Each allergy entry must be associated with a specific patient and substance.
        # - Patient data is kept secure and confidential in compliance with health privacy regulations (e.g., HIPAA).
        # - The system ensures a unique patient identity via patient_id.

        self.init_config = init_config

    def verify_user_authorization(self, user_id: str, patient_id: str, action: str) -> dict:
        """
        Determine whether a user (by user_id) has rights to access or modify the given patient’s record.

        Args:
            user_id (str): ID of the user attempting to access/modify the record.
            patient_id (str): ID of the patient whose data is being accessed.
            action (str): Requested action; valid values are 'view' or 'modify'.

        Returns:
            dict: {
                "success": True,
                "authorized": bool,
                "details": str  # explanation if authorized/denied
            }
            or {
                "success": False,
                "error": str   # reason for failure
            }

        Constraints:
            - Only users in authorized_users may access patient data.
            - The user must have relevant rights for requested action.
            - Patient must exist (identity via patient_id).
            - Supported actions: 'view', 'modify'
        """
        if user_id not in self.authorized_users:
            return { "success": False, "error": "User does not exist or is not authorized" }

        if patient_id not in self.patients:
            return { "success": False, "error": "Patient record does not exist" }

        if action not in ["view", "modify"]:
            return { "success": False, "error": f"Invalid action '{action}'. Allowed: 'view', 'modify'" }

        user_info = self.authorized_users[user_id]
        if action in user_info.get("access_rights", []):
            return {
                "success": True,
                "authorized": True,
                "details": f"User '{user_id}' is authorized to {action} the record for patient '{patient_id}'."
            }
        else:
            return {
                "success": True,
                "authorized": False,
                "details": f"User '{user_id}' does not have '{action}' rights for patient records."
            }

    def get_authorized_user_info(self, user_id: str) -> dict:
        """
        Retrieve the details (name, role, access rights) for an authorized user.

        Args:
            user_id (str): The unique ID of the authorized user.

        Returns:
            dict:
                - On success: {
                    "success": True,
                    "data": AuthorizedUserInfo  # The authorized user's info
                  }
                - On failure: {
                    "success": False,
                    "error": "Authorized user not found"
                  }

        Constraints:
            - user_id must exist in the system.
        """
        user_info = self.authorized_users.get(user_id)
        if not user_info:
            return { "success": False, "error": "Authorized user not found" }
        return { "success": True, "data": user_info }

    def get_patient_by_id(self, user_id: str, patient_id: str) -> dict:
        """
        Retrieve complete demographic and medical history for a patient by patient_id.

        Args:
            user_id (str): Authorized user's unique identifier.
            patient_id (str): Patient's unique identifier.

        Returns:
            dict: {
                "success": True,
                "data": PatientInfo,  # Patient info with demographics and medical history
            } OR {
                "success": False,
                "error": str  # Error reason (unauthorized/user/patient not found)
            }

        Constraints:
            - Only authorized users may view patient data.
            - Patient must exist in the system.
        """
        user = self.authorized_users.get(user_id)
        if user is None:
            return { "success": False, "error": "User does not exist" }
        # Check access rights, assuming "view_patient" is required
        if not user.get("access_rights") or "view_patient" not in user["access_rights"]:
            return { "success": False, "error": "User not authorized to view patient records" }

        patient = self.patients.get(patient_id)
        if patient is None:
            return { "success": False, "error": "Patient not found" }

        return { "success": True, "data": patient }

    def get_patient_by_demographics(
        self,
        requesting_user_id: str,
        name: str = None,
        date_of_birth: str = None,
        demographic_info: dict = None
    ) -> dict:
        """
        Search for patient(s) using demographic information such as name, date_of_birth, or fields within demographic_info.

        Inputs:
            requesting_user_id (str): ID of the user performing the search; must be authorized.
            name (str, optional): Patient's name to search for.
            date_of_birth (str, optional): Patient's birth date to search for.
            demographic_info (dict, optional): Subset of demographic_info to match.

        Returns:
            dict: {
                "success": True,
                "data": List[PatientInfo],  # List of matching patients (may be empty),
            }
            OR
            {
                "success": False,
                "error": str,  # Reason for failure (not authorized, bad input, etc.)
            }

        Constraints:
            - Only authorized users may view patient records.
            - Patient data is confidential.
        """
        user = self.authorized_users.get(requesting_user_id)
        if not user:
            return {"success": False, "error": "Requesting user does not exist"}
        if "view_patient_records" not in user.get("access_rights", []):
            return {"success": False, "error": "User is not authorized to view patient records"}

        matches = []
        for patient in self.patients.values():
            match = True
            if name is not None and patient.get("name") != name:
                match = False
            if date_of_birth is not None and patient.get("date_of_birth") != date_of_birth:
                match = False
            if demographic_info is not None:
                # Demographic info in patient may contain more keys; require all keys/values in demographic_info to match
                patient_demo = patient.get("demographic_info", {})
                for k, v in demographic_info.items():
                    if patient_demo.get(k) != v:
                        match = False
                        break
            if match:
                matches.append(patient)
        return {"success": True, "data": matches}

    def list_patient_allergies(self, requesting_user_id: str, patient_id: str) -> dict:
        """
        Retrieve all allergy records associated with a specific patient.
        Only authorized users may access patient allergy information.

        Args:
            requesting_user_id (str): The user ID of the individual making the request.
            patient_id (str): The unique identifier of the patient being queried.

        Returns:
            dict: {
                "success": True,
                "data": List[AllergyInfo],  # May be empty if no allergies.
            }
            OR
            {
                "success": False,
                "error": str  # Reason for failure (e.g., unauthorized, patient not found)
            }

        Constraints:
            - Access permitted only for authorized users (self.authorized_users must contain requesting_user_id).
            - Patient must exist in self.patients.
            - Patient allergies list may be empty.
        """
        user = self.authorized_users.get(requesting_user_id)
        if user is None or "view_patient_records" not in user.get("access_rights", []):
            return { "success": False, "error": "Unauthorized access" }

        if patient_id not in self.patients:
            return { "success": False, "error": "Patient not found" }

        allergies = self.allergies.get(patient_id, [])
        return { "success": True, "data": allergies }

    def get_patient_allergy_by_substance(self, user_id: str, patient_id: str, substance: str) -> dict:
        """
        Query allergy records for a patient filtered by a specific substance (e.g., Penicillin).

        Args:
            user_id (str): The ID of the requesting authorized user.
            patient_id (str): The ID of the patient whose allergies to query.
            substance (str): The allergen name to filter (case-insensitive).

        Returns:
            dict: {
                "success": True,
                "data": List[AllergyInfo]  # List may be empty if no allergy records for the substance
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure (e.g. access denied, patient not found)
            }

        Constraints:
            - Only authorized users may view patient health records (must have 'view_patient' or similar rights).
            - Patient must exist.
        """
        # Check user existence and access rights
        user_info = self.authorized_users.get(user_id)
        if not user_info or not any(
            right in user_info.get("access_rights", []) for right in ["view_patient", "view_allergy", "all"]
        ):
            return { "success": False, "error": "Access denied" }

        # Check patient existence
        if patient_id not in self.patients:
            return { "success": False, "error": "Patient not found" }

        # Get allergy records for this patient
        allergies = self.allergies.get(patient_id, [])
        substance_lower = substance.strip().lower()
        filtered = [
            allergy for allergy in allergies
            if allergy.get("substance", "").strip().lower() == substance_lower
        ]

        return { "success": True, "data": filtered }

    def get_allergy_details(self, user_id: str, patient_id: str, substance: str) -> dict:
        """
        Fetch full details (reaction, confirmation, date) for a patient's specific allergy record.

        Args:
            user_id (str): The ID of the authorized user requesting access.
            patient_id (str): The ID of the patient whose allergy is being queried.
            substance (str): The name of the allergy substance (e.g., 'Penicillin').

        Returns:
            dict: {
                "success": True,
                "data": AllergyInfo  # Detailed allergy record for the patient/substance.
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure: unauthorized, patient not found, allergy not found, etc.
            }

        Constraints:
            - Only authorized users may view patient health records.
            - Each allergy entry must be associated with a specific patient and substance.
            - Patient data is kept secure and confidential.
        """
        # Check user authorization
        user = self.authorized_users.get(user_id)
        if not user:
            return {"success": False, "error": "User not authorized"}

        # Assume 'view_allergies' is required in access_rights for this operation
        if "view_allergies" not in user.get("access_rights", []):
            return {"success": False, "error": "Insufficient permissions to view allergy data"}

        # Check patient existence
        if patient_id not in self.patients:
            return {"success": False, "error": "Patient not found"}

        # Retrieve allergies for the patient
        patient_allergies = self.allergies.get(patient_id, [])
        for allergy in patient_allergies:
            if allergy.get("substance") == substance:
                return {"success": True, "data": allergy}

        return {"success": False, "error": "Allergy record for specified substance not found for this patient"}

    def get_all_patients(self, user_id: str) -> dict:
        """
        List all patients in the EHR system for an authorized user.

        Args:
            user_id (str): ID of the user requesting the patient list.

        Returns:
            dict: {
                "success": True,
                "data": List[PatientInfo]  # All patients in the system, may be empty
            }
            or
            {
                "success": False,
                "error": str  # Reason: unauthorized or user does not exist
            }

        Constraints:
            - Only authorized users may view patient health records.
            - User must have appropriate access_rights ("view_patients" or "admin").
            - Patient data is kept confidential.
        """
        user = self.authorized_users.get(user_id)
        if not user:
            return {"success": False, "error": "User ID does not exist or is not authorized."}

        allowed_rights = set(user.get("access_rights", []))
        if "view_patients" not in allowed_rights and "admin" not in allowed_rights:
            return {"success": False, "error": "User does not have permission to view patient list."}

        return {"success": True, "data": list(self.patients.values())}

    def get_patient_medications(self, requesting_user_id: str, patient_id: str) -> dict:
        """
        Retrieve medication history records for a patient if the requesting user is authorized.

        Args:
            requesting_user_id (str): The ID of the user requesting the data.
            patient_id (str): The unique identifier for the patient whose medication history is requested.

        Returns:
            dict: 
                - On success:
                    {
                        "success": True,
                        "data": List[MedicationInfo]  # Possibly empty if no medications
                    }
                - On error (unauthorized or not found):
                    {
                        "success": False,
                        "error": str  # Error message describing issue
                    }

        Constraints:
            - Only authorized users may view patient medication records.
            - Patient_id must exist.
            - Medication records returned only if authorization succeeds.
        """
        # Check user exists and is authorized
        user_info = self.authorized_users.get(requesting_user_id)
        if not user_info:
            return { "success": False, "error": "User not authorized" }
        # If fine-grained access rights are required, check for specific right
        # e.g., if "view_medications" in user_info["access_rights"]
        if "view_medications" not in user_info.get("access_rights", []):
            return { "success": False, "error": "User does not have permission to view medications" }
        # Check patient exists
        if patient_id not in self.patients:
            return { "success": False, "error": "Patient not found" }
        # Retrieve medication history
        medications = self.medications.get(patient_id, [])
        return { "success": True, "data": medications }

    def get_patient_laboratory_results(self, requesting_user_id: str, patient_id: str) -> dict:
        """
        Fetch all laboratory results for a patient.

        Args:
            requesting_user_id (str): The user ID of the person requesting the results.
            patient_id (str): The unique patient ID to query.

        Returns:
            dict: {
                "success": True,
                "data": List[LaboratoryResultInfo],  # May be empty if no results
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure (unauthorized, not found, etc.)
            }

        Constraints:
            - Only authorized users with proper access rights may perform this query.
            - Patient must exist in the system.
            - Data returned is a list of laboratory result records for the given patient.
        """
        user_info = self.authorized_users.get(requesting_user_id)
        if user_info is None:
            return { "success": False, "error": "Unauthorized access: user not found" }

        # Check for necessary access rights. Typically 'view_lab_results' or 'view_patient_data'.
        has_access = False
        for right in user_info.get("access_rights", []):
            if right in ("view_lab_results", "view_patient_data", "admin"):
                has_access = True
                break
        if not has_access:
            return { "success": False, "error": "Unauthorized access: insufficient permissions" }

        if patient_id not in self.patients:
            return { "success": False, "error": "Patient not found" }

        results = self.laboratory_results.get(patient_id, [])
        return { "success": True, "data": results }

    def add_patient_allergy(
        self,
        user_id: str,
        patient_id: str,
        substance: str,
        reaction_type: str,
        confirmation_status: str,
        date_recorded: str
    ) -> dict:
        """
        Add a new allergy record for a patient, specifying substance, reaction type, and confirmation status.

        Args:
            user_id (str): User performing the operation (must have appropriate modification rights).
            patient_id (str): Patient to add the allergy for.
            substance (str): Allergen (e.g., "Penicillin").
            reaction_type (str): Type of reaction (e.g., "Anaphylaxis", "Rash").
            confirmation_status (str): Status ("Confirmed", "Unconfirmed", etc.).
            date_recorded (str): Date the allergy is recorded (ISO date).

        Returns:
            dict:
                On success: { "success": True, "message": "Allergy record added for patient <patient_id>" }
                On failure: { "success": False, "error": "<reason>" }

        Constraints:
            - Only authorized users with modification rights may add allergy records.
            - patient_id must exist.
            - substance must be provided.
            - Each allergy entry must be unique for patient and substance.
        """
        # Check: authorized user exists
        user = self.authorized_users.get(user_id)
        if not user:
            return { "success": False, "error": "User not authorized" }

        # Check: access rights
        allowed_rights = set(user.get("access_rights", []))
        if "modify_allergy" not in allowed_rights and "add_allergy" not in allowed_rights and "admin" not in allowed_rights:
            return { "success": False, "error": "User lacks add allergy permissions" }

        # Check: patient exists
        if patient_id not in self.patients:
            return { "success": False, "error": "Patient not found" }

        # Check: substance is provided
        if not substance or not substance.strip():
            return { "success": False, "error": "Substance must be specified" }

        # Check: allergy uniqueness for same substance
        existing_allergies = self.allergies.get(patient_id, [])
        for allergy in existing_allergies:
            if allergy["substance"].lower() == substance.lower():
                return { "success": False, "error": "Allergy for this substance already exists for the patient" }

        # Build new allergy
        new_allergy: AllergyInfo = {
            "patient_id": patient_id,
            "substance": substance,
            "reaction_type": reaction_type,
            "confirmation_status": confirmation_status,
            "date_recorded": date_recorded
        }

        # Add to allergy records
        if patient_id not in self.allergies:
            self.allergies[patient_id] = []
        self.allergies[patient_id].append(new_allergy)

        return { "success": True, "message": f"Allergy record added for patient {patient_id}" }

    def update_patient_allergy(
        self,
        user_id: str,
        patient_id: str,
        substance: str,
        reaction_type: str = None,
        confirmation_status: str = None,
        date_recorded: str = None,
    ) -> dict:
        """
        Modify an existing allergy entry for a patient.

        Args:
            user_id (str): Authorized user's ID attempting the update.
            patient_id (str): The patient whose allergy entry is to be modified.
            substance (str): The allergen/substance whose allergy info to update.
            reaction_type (str, optional): The new reaction type, if being updated.
            confirmation_status (str, optional): The new confirmation status, if being updated.
            date_recorded (str, optional): The new date recorded, if being updated.

        Returns:
            dict: {
                "success": True,
                "message": "Allergy entry updated for patient {patient_id} and substance {substance}"
            }
            or
            {
                "success": False,
                "error": str
            }

        Constraints:
            - Only authorized users may modify patient health records.
            - Allergy entry must exist for specified patient and substance.
            - Patient data confidentiality is enforced by authorization check.
        """
        # Authorization check
        user = self.authorized_users.get(user_id)
        if user is None or "modify_records" not in user.get("access_rights", []):
            return { "success": False, "error": "User not authorized to modify patient records" }

        if patient_id not in self.patients:
            return { "success": False, "error": "Patient not found" }

        allergy_list = self.allergies.get(patient_id, [])
        # Find allergy entry by substance
        allergy = next((entry for entry in allergy_list if entry["substance"].lower() == substance.lower()), None)
        if allergy is None:
            return { "success": False, "error": f"Allergy to '{substance}' not found for patient" }

        updated = False
        if reaction_type is not None:
            allergy["reaction_type"] = reaction_type
            updated = True
        if confirmation_status is not None:
            allergy["confirmation_status"] = confirmation_status
            updated = True
        if date_recorded is not None:
            allergy["date_recorded"] = date_recorded
            updated = True

        if not updated:
            return { "success": False, "error": "No update fields provided" }

        return {
            "success": True,
            "message": f"Allergy entry updated for patient {patient_id} and substance '{substance}'"
        }

    def delete_patient_allergy(self, user_id: str, patient_id: str, substance: str) -> dict:
        """
        Remove all allergy entries for a specific substance from a given patient's record.

        Args:
            user_id (str): The ID of the authorized user performing the operation.
            patient_id (str): The unique patient identifier.
            substance (str): The allergen to remove (case-insensitive match).

        Returns:
            dict: {
                "success": True,
                "message": "Allergy entry removed from patient record."
            }
            or
            {
                "success": False,
                "error": str  # error description
            }

        Constraints:
            - Only authorized users with appropriate access may perform this operation.
            - If no matching allergy is found, indicate with error.
        """
        # Check user exists and is authorized
        user_info = self.authorized_users.get(user_id)
        if not user_info:
            return { "success": False, "error": "User not found or unauthorized." }
        # Rights check (example: must have 'modify_allergies' in access_rights or be 'admin')
        allowed = 'modify_allergies' in user_info['access_rights'] or user_info['role'].lower() == 'admin'
        if not allowed:
            return { "success": False, "error": "Insufficient rights to modify allergies." }

        # Check patient exists
        if patient_id not in self.patients:
            return { "success": False, "error": "Patient not found." }

        # Find/Remove allergy entries for substance
        allergy_list = self.allergies.get(patient_id, [])
        initial_count = len(allergy_list)
        # Use case-insensitive matching for substance
        new_list = [
            entry for entry in allergy_list
            if entry["substance"].strip().lower() != substance.strip().lower()
        ]
        deleted_count = initial_count - len(new_list)

        if deleted_count == 0:
            return { "success": False, "error": "No matching allergy entry found for the specified substance." }

        # Update the allergies list for the patient
        self.allergies[patient_id] = new_list

        return {
            "success": True,
            "message": f"Allergy entry for substance '{substance}' removed from patient record."
        }

    def add_authorized_user(self, user_id: str, name: str, role: str, access_rights: List[str]) -> dict:
        """
        Add a new authorized user to the system.

        Args:
            user_id (str): Unique identifier for the user.
            name (str): User's full name.
            role (str): Role designation (e.g., 'clinician', 'staff').
            access_rights (List[str]): List of access rights granted to user.

        Returns:
            dict: {
                "success": True,
                "message": "Authorized user added successfully."
            }
            or
            {
                "success": False,
                "error": "reason for failure (e.g., user_id exists, invalid input)"
            }

        Constraints:
            - user_id must be unique (not already present in authorized_users).
            - access_rights must be a non-empty list of strings.
            - name and role must be non-empty strings.
        """
        if not isinstance(user_id, str) or not user_id.strip():
            return { "success": False, "error": "Invalid or empty user_id." }
        if user_id in self.authorized_users:
            return { "success": False, "error": "User ID already exists." }
        if not isinstance(name, str) or not name.strip():
            return { "success": False, "error": "Invalid or empty name." }
        if not isinstance(role, str) or not role.strip():
            return { "success": False, "error": "Invalid or empty role." }
        if not isinstance(access_rights, list) or not access_rights or not all(isinstance(x, str) and x.strip() for x in access_rights):
            return { "success": False, "error": "access_rights must be a non-empty list of strings." }

        new_user: AuthorizedUserInfo = {
            "user_id": user_id,
            "name": name,
            "role": role,
            "access_rights": access_rights
        }
        self.authorized_users[user_id] = new_user

        return { "success": True, "message": "Authorized user added successfully." }

    def update_authorized_user_rights(
        self,
        admin_user_id: str,
        target_user_id: str,
        new_access_rights: List[str]
    ) -> dict:
        """
        Change the access permissions (access_rights) of a system user.

        Args:
            admin_user_id (str): The user ID of the requester (must be authorized to modify rights).
            target_user_id (str): The user ID of the user whose rights are being changed.
            new_access_rights (List[str]): The new set of access rights to assign.

        Returns:
            dict: {
                "success": True,
                "message": "Access rights updated for user <target_user_id>."
            }
            or
            {
                "success": False,
                "error": "<Error description>"
            }

        Constraints:
            - Only authorized users with proper role/rights (e.g., 'manage_users' in access_rights) can modify user access rights.
            - The target user must exist.
            - new_access_rights must be a list of strings.
        """
        # Verify requesting (admin) user exists
        admin_info = self.authorized_users.get(admin_user_id)
        if not admin_info:
            return { "success": False, "error": "Requesting user not found or unauthorized." }

        # Check if admin has required permission
        if "manage_users" not in admin_info.get("access_rights", []):
            return { "success": False, "error": "Permission denied. User cannot update other users' rights." }

        # Verify target user exists
        target_info = self.authorized_users.get(target_user_id)
        if not target_info:
            return { "success": False, "error": "Target user not found." }

        # Check new_access_rights
        if not isinstance(new_access_rights, list) or not all(isinstance(r, str) for r in new_access_rights):
            return { "success": False, "error": "new_access_rights must be a list of strings." }

        # Update rights
        self.authorized_users[target_user_id]["access_rights"] = new_access_rights

        return {
            "success": True,
            "message": f"Access rights updated for user {target_user_id}."
        }

    def delete_authorized_user(self, requester_user_id: str, target_user_id: str) -> dict:
        """
        Remove an authorized user from the system, ensuring security and authorization.

        Args:
            requester_user_id (str): The user_id of the individual requesting the deletion.
            target_user_id (str): The user_id of the authorized user to delete.

        Returns:
            dict: {
                "success": True,
                "message": "Authorized user <target_user_id> deleted"
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure (permission denied, user does not exist, etc.)
            }

        Constraints:
            - Only an authorized user with 'manage_users' in access_rights may perform this operation.
            - Target user must exist in the system.
            - Optional: Requester cannot delete themselves.
        """
        # Check requester exists
        requester = self.authorized_users.get(requester_user_id)
        if not requester:
            return { "success": False, "error": "Requester does not exist or is not authorized." }

        # Check permission
        if "manage_users" not in requester.get("access_rights", []):
            return { "success": False, "error": "Permission denied. User lacks rights to manage authorized users." }

        # Cannot delete self
        if requester_user_id == target_user_id:
            return { "success": False, "error": "Users cannot delete themselves." }

        # Check target exists
        if target_user_id not in self.authorized_users:
            return { "success": False, "error": "Target authorized user does not exist." }

        # Delete user
        del self.authorized_users[target_user_id]
        return { "success": True, "message": f"Authorized user {target_user_id} deleted" }

