def verify_user_authorization(self, user_id: str, patient_id: str, action: str) -> dict:
    """
    Determine whether a user (by user_id) has rights to access or modify the given patient’s record.

    Args:
        user_id (str): ID of the user attempting to access/modify the record.
        patient_id (str): ID of the patient whose data is being accessed.
        action (str): Requested action; valid values are 'view' or 'modify'.

    Returns:
        dict: {
            "success": True,
            "authorized": bool,
            "details": str  # explanation if authorized/denied
        }
        or {
            "success": False,
            "error": str   # reason for failure
        }

    Constraints:
        - Only users in authorized_users may access patient data.
        - The user must have relevant rights for requested action.
        - Patient must exist (identity via patient_id).
        - Supported actions: 'view', 'modify'
    """
    if user_id not in self.authorized_users:
        return { "success": False, "error": "User does not exist or is not authorized" }

    if patient_id not in self.patients:
        return { "success": False, "error": "Patient record does not exist" }

    if action not in ["view", "modify"]:
        return { "success": False, "error": f"Invalid action '{action}'. Allowed: 'view', 'modify'" }

    user_info = self.authorized_users[user_id]
    if action in user_info.get("access_rights", []):
        return {
            "success": True,
            "authorized": True,
            "details": f"User '{user_id}' is authorized to {action} the record for patient '{patient_id}'."
        }
    else:
        return {
            "success": True,
            "authorized": False,
            "details": f"User '{user_id}' does not have '{action}' rights for patient records."
        }

