def get_patient_by_id(self, user_id: str, patient_id: str) -> dict:
    """
    Retrieve complete demographic and medical history for a patient by patient_id.

    Args:
        user_id (str): Authorized user's unique identifier.
        patient_id (str): Patient's unique identifier.

    Returns:
        dict: {
            "success": True,
            "data": PatientInfo,  # Patient info with demographics and medical history
        } OR {
            "success": False,
            "error": str  # Error reason (unauthorized/user/patient not found)
        }

    Constraints:
        - Only authorized users may view patient data.
        - Patient must exist in the system.
    """
