    if not user.get("access_rights") or "view_patient" not in user["access_rights"]:
        return { "success": False, "error": "User not authorized to view patient records" }

    patient = self.patients.get(patient_id)
    if patient is None:
        return { "success": False, "error": "Patient not found" }

    return { "success": True, "data": patient }

