def get_patient_allergy_by_substance(self, user_id: str, patient_id: str, substance: str) -> dict:
    """
    Query allergy records for a patient filtered by a specific substance (e.g., Penicillin).

    Args:
        user_id (str): The ID of the requesting authorized user.
        patient_id (str): The ID of the patient whose allergies to query.
        substance (str): The allergen name to filter (case-insensitive).

    Returns:
        dict: {
            "success": True,
            "data": List[AllergyInfo]  # List may be empty if no allergy records for the substance
        }
        or
        {
            "success": False,
            "error": str  # Reason for failure (e.g. access denied, patient not found)
        }

    Constraints:
        - Only authorized users may view patient health records (must have 'view_patient' or similar rights).
        - Patient must exist.
    """
    # Check user existence and access rights
    user_info = self.authorized_users.get(user_id)
    if not user_info or not any(
        right in user_info.get("access_rights", []) for right in ["view_patient", "view_allergy", "all"]
    ):
        return { "success": False, "error": "Access denied" }

    # Check patient existence
    if patient_id not in self.patients:
        return { "success": False, "error": "Patient not found" }

    # Get allergy records for this patient
    allergies = self.allergies.get(patient_id, [])
    substance_lower = substance.strip().lower()
    filtered = [
        allergy for allergy in allergies
        if allergy.get("substance", "").strip().lower() == substance_lower
    ]

    return { "success": True, "data": filtered }

