def get_all_patients(self, user_id: str) -> dict:
    """
    List all patients in the EHR system for an authorized user.

    Args:
        user_id (str): ID of the user requesting the patient list.

    Returns:
        dict: {
            "success": True,
            "data": List[PatientInfo]  # All patients in the system, may be empty
        }
        or
        {
            "success": False,
            "error": str  # Reason: unauthorized or user does not exist
        }

    Constraints:
        - Only authorized users may view patient health records.
