        - Patient data is kept confidential.
    """
    user = self.authorized_users.get(user_id)
    if not user:
        return {"success": False, "error": "User ID does not exist or is not authorized."}

    allowed_rights = set(user.get("access_rights", []))
    if "view_patients" not in allowed_rights and "admin" not in allowed_rights:
        return {"success": False, "error": "User does not have permission to view patient list."}

    return {"success": True, "data": list(self.patients.values())}

