def get_patient_medications(self, requesting_user_id: str, patient_id: str) -> dict:
    """
    Retrieve medication history records for a patient if the requesting user is authorized.

    Args:
        requesting_user_id (str): The ID of the user requesting the data.
        patient_id (str): The unique identifier for the patient whose medication history is requested.

    Returns:
        dict: 
            - On success:
                {
                    "success": True,
                    "data": List[MedicationInfo]  # Possibly empty if no medications
                }
            - On error (unauthorized or not found):
                {
                    "success": False,
                    "error": str  # Error message describing issue
                }

    Constraints:
        - Only authorized users may view patient medication records.
        - Patient_id must exist.
        - Medication records returned only if authorization succeeds.
    """
    # Check user exists and is authorized
    user_info = self.authorized_users.get(requesting_user_id)
    if not user_info:
        return { "success": False, "error": "User not authorized" }
    # If fine-grained access rights are required, check for specific right
    # e.g., if "view_medications" in user_info["access_rights"]
    if "view_medications" not in user_info.get("access_rights", []):
        return { "success": False, "error": "User does not have permission to view medications" }
