def get_patient_laboratory_results(self, requesting_user_id: str, patient_id: str) -> dict:
    """
    Fetch all laboratory results for a patient.

    Args:
        requesting_user_id (str): The user ID of the person requesting the results.
        patient_id (str): The unique patient ID to query.

    Returns:
        dict: {
            "success": True,
            "data": List[LaboratoryResultInfo],  # May be empty if no results
        }
        or
        {
            "success": False,
            "error": str  # Reason for failure (unauthorized, not found, etc.)
        }

    Constraints:
        - Only authorized users with proper access rights may perform this query.
        - Patient must exist in the system.
        - Data returned is a list of laboratory result records for the given patient.
    """
    user_info = self.authorized_users.get(requesting_user_id)
    if user_info is None:
        return { "success": False, "error": "Unauthorized access: user not found" }

    # Check for necessary access rights. Typically 'view_lab_results' or 'view_patient_data'.
    has_access = False
    for right in user_info.get("access_rights", []):
        if right in ("view_lab_results", "view_patient_data", "admin"):
            has_access = True
            break
    if not has_access:
        return { "success": False, "error": "Unauthorized access: insufficient permissions" }

    if patient_id not in self.patients:
        return { "success": False, "error": "Patient not found" }

    results = self.laboratory_results.get(patient_id, [])
    return { "success": True, "data": results }

add_patient_allergy.source_code:
def add_patient_allergy(
    self,
    user_id: str,
    patient_id: str,
    substance: str,
    reaction_type: str,
    confirmation_status: str,
    date_recorded: str
) -> dict:
    """
    Add a new allergy record for a patient, specifying substance, reaction type, and confirmation status.

    Args:
        user_id (str): User performing the operation (must have appropriate modification rights).
        patient_id (str): Patient to add the allergy for.
        substance (str): Allergen (e.g., "Penicillin").
        reaction_type (str): Type of reaction (e.g., "Anaphylaxis", "Rash").
        confirmation_status (str): Status ("Confirmed", "Unconfirmed", etc.).
        date_recorded (str): Date the allergy is recorded (ISO date).

    Returns:
        dict:
            On success: { "success": True, "message": "Allergy record added for patient <patient_id>" }
            On failure: { "success": False, "error": "<reason>" }

    Constraints:
        - Only authorized users with modification rights may add allergy records.
        - patient_id must exist.
        - substance must be provided.
        - Each allergy entry must be unique for patient and substance.
    """
    # Check: authorized user exists
    user = self.authorized_users.get(user_id)
    if not user:
        return { "success": False, "error": "User not authorized" }

    # Check: access rights
    allowed_rights = set(user.get("access_rights", []))
    if "modify_allergy" not in allowed_rights and "add_allergy" not in allowed_rights and "admin" not in allowed_rights:
        return { "success": False, "error": "User lacks add allergy permissions" }

    # Check: patient exists
    if patient_id not in self.patients:
        return { "success": False, "error": "Patient not found" }

    # Check: substance is provided
    if not substance or not substance.strip():
        return { "success": False, "error": "Substance must be specified" }

    # Check: allergy uniqueness for same substance
    existing_allergies = self.allergies.get(patient_id, [])
    for allergy in existing_allergies:
        if allergy["substance"].lower() == substance.lower():
            return { "success": False, "error": "Allergy for this substance already exists for the patient" }

    # Build new allergy
    new_allergy: AllergyInfo = {
        "patient_id": patient_id,
        "substance": substance,
        "reaction_type": reaction_type,
        "confirmation_status": confirmation_status,
        "date_recorded": date_recorded
    }

    # Add to allergy records
    if patient_id not in self.allergies:
        self.allergies[patient_id] = []
    self.allergies[patient_id].append(new_allergy)

    return { "success": True, "message": f"Allergy record added for patient {patient_id}" }

