def update_patient_allergy(
    self,
    user_id: str,
    patient_id: str,
    substance: str,
    reaction_type: str = None,
    confirmation_status: str = None,
    date_recorded: str = None,
) -> dict:
    """
    Modify an existing allergy entry for a patient.

    Args:
        user_id (str): Authorized user's ID attempting the update.
        patient_id (str): The patient whose allergy entry is to be modified.
        substance (str): The allergen/substance whose allergy info to update.
        reaction_type (str, optional): The new reaction type, if being updated.
        confirmation_status (str, optional): The new confirmation status, if being updated.
        date_recorded (str, optional): The new date recorded, if being updated.

    Returns:
        dict: {
            "success": True,
            "message": "Allergy entry updated for patient {patient_id} and substance {substance}"
        }
        or
        {
            "success": False,
            "error": str
        }

    Constraints:
        - Only authorized users may modify patient health records.
        - Allergy entry must exist for specified patient and substance.
        - Patient data confidentiality is enforced by authorization check.
    """
    # Authorization check
    user = self.authorized_users.get(user_id)
    if user is None or "modify_records" not in user.get("access_rights", []):
        return { "success": False, "error": "User not authorized to modify patient records" }

    if patient_id not in self.patients:
        return { "success": False, "error": "Patient not found" }

    allergy_list = self.allergies.get(patient_id, [])
    # Find allergy entry by substance
    allergy = next((entry for entry in allergy_list if entry["substance"].lower() == substance.lower()), None)
    if allergy is None:
        return { "success": False, "error": f"Allergy to '{substance}' not found for patient" }

    updated = False
    if reaction_type is not None:
        allergy["reaction_type"] = reaction_type
        updated = True
    if confirmation_status is not None:
        allergy["confirmation_status"] = confirmation_status
        updated = True
    if date_recorded is not None:
        allergy["date_recorded"] = date_recorded
        updated = True

    if not updated:
        return { "success": False, "error": "No update fields provided" }

    return {
        "success": True,
        "message": f"Allergy entry updated for patient {patient_id} and substance '{substance}'"
    }

