def add_authorized_user(self, user_id: str, name: str, role: str, access_rights: List[str]) -> dict:
    """
    Add a new authorized user to the system.

    Args:
        user_id (str): Unique identifier for the user.
        name (str): User's full name.
        role (str): Role designation (e.g., 'clinician', 'staff').
        access_rights (List[str]): List of access rights granted to user.

    Returns:
        dict: {
            "success": True,
            "message": "Authorized user added successfully."
        }
        or
        {
            "success": False,
            "error": "reason for failure (e.g., user_id exists, invalid input)"
        }

    Constraints:
        - user_id must be unique (not already present in authorized_users).
        - access_rights must be a non-empty list of strings.
        - name and role must be non-empty strings.
    """
    if not isinstance(user_id, str) or not user_id.strip():
        return { "success": False, "error": "Invalid or empty user_id." }
    if user_id in self.authorized_users:
        return { "success": False, "error": "User ID already exists." }
    if not isinstance(name, str) or not name.strip():
        return { "success": False, "error": "Invalid or empty name." }
    if not isinstance(role, str) or not role.strip():
        return { "success": False, "error": "Invalid or empty role." }
    if not isinstance(access_rights, list) or not access_rights or not all(isinstance(x, str) and x.strip() for x in access_rights):
        return { "success": False, "error": "access_rights must be a non-empty list of strings." }

    new_user: AuthorizedUserInfo = {
        "user_id": user_id,
        "name": name,
        "role": role,
        "access_rights": access_rights
    }
    self.authorized_users[user_id] = new_user

    return { "success": True, "message": "Authorized user added successfully." }

