def update_authorized_user_rights(
    self,
    admin_user_id: str,
    target_user_id: str,
    new_access_rights: List[str]
) -> dict:
    """
    Change the access permissions (access_rights) of a system user.

    Args:
        admin_user_id (str): The user ID of the requester (must be authorized to modify rights).
        target_user_id (str): The user ID of the user whose rights are being changed.
        new_access_rights (List[str]): The new set of access rights to assign.

    Returns:
        dict: {
            "success": True,
            "message": "Access rights updated for user <target_user_id>."
        }
        or
        {
            "success": False,
            "error": "<Error description>"
        }

    Constraints:
        - Only authorized users with proper role/rights (e.g., 'manage_users' in access_rights) can modify user access rights.
        - The target user must exist.
        - new_access_rights must be a list of strings.
    """
    # Verify requesting (admin) user exists
    admin_info = self.authorized_users.get(admin_user_id)
    if not admin_info:
        return { "success": False, "error": "Requesting user not found or unauthorized." }

    # Check if admin has required permission
    if "manage_users" not in admin_info.get("access_rights", []):
        return { "success": False, "error": "Permission denied. User cannot update other users' rights." }

    # Verify target user exists
    target_info = self.authorized_users.get(target_user_id)
    if not target_info:
        return { "success": False, "error": "Target user not found." }

    # Check new_access_rights
    if not isinstance(new_access_rights, list) or not all(isinstance(r, str) for r in new_access_rights):
        return { "success": False, "error": "new_access_rights must be a list of strings." }

    # Update rights
    self.authorized_users[target_user_id]["access_rights"] = new_access_rights

    return {
        "success": True,
        "message": f"Access rights updated for user {target_user_id}."
    }

delete_authorized_user.source_code:
def delete_authorized_user(self, requester_user_id: str, target_user_id: str) -> dict:
    """
    Remove an authorized user from the system, ensuring security and authorization.

    Args:
        requester_user_id (str): The user_id of the individual requesting the deletion.
        target_user_id (str): The user_id of the authorized user to delete.

    Returns:
        dict: {
            "success": True,
            "message": "Authorized user <target_user_id> deleted"
        }
        or
        {
            "success": False,
            "error": str  # Reason for failure (permission denied, user does not exist, etc.)
        }

    Constraints:
        - Only an authorized user with 'manage_users' in access_rights may perform this operation.
        - Target user must exist in the system.
        - Optional: Requester cannot delete themselves.
    """
    # Check requester exists
    requester = self.authorized_users.get(requester_user_id)
    if not requester:
        return { "success": False, "error": "Requester does not exist or is not authorized." }

    # Check permission
    if "manage_users" not in requester.get("access_rights", []):
        return { "success": False, "error": "Permission denied. User lacks rights to manage authorized users." }

    # Cannot delete self
    if requester_user_id == target_user_id:
        return { "success": False, "error": "Users cannot delete themselves." }

    # Check target exists
    if target_user_id not in self.authorized_users:
        return { "success": False, "error": "Target authorized user does not exist." }

    # Delete user
    del self.authorized_users[target_user_id]
    return { "success": True, "message": f"Authorized user {target_user_id} deleted" }

